INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(221, 'Wakil Muda ASEAN', 'Wakil muda yang menghadiri sidang serantau dengan fail penuh nota (watak rekaan).', 'Menyampaikan kisah pertubuhan serantau dan sumbangan Malaysia.', 'wakil_asean.png'),
(222, 'Penjaga Keamanan PBB', 'Anggota pasukan pengaman yang bertugas dengan topi biru (watak rekaan).', 'Menyampaikan kisah sumbangan Malaysia kepada PBB dan pertubuhan dunia.', 'penjaga_keamanan_pbb.png'),
(223, 'Pemandu Pameran UNESCO', 'Pemandu pameran yang menjaga bilik warisan dunia (watak rekaan).', 'Menyampaikan kisah warisan Malaysia yang diiktiraf dunia.', 'ahli_antropologi_UNESCO.png'),
(224, 'Pakar Ekonomi ASEAN', 'Pakar yang menjelaskan matlamat dan kerjasama ASEAN (watak rekaan).', 'Menerangkan matlamat dan sumbangan Malaysia dalam ASEAN.', 'pakar_ekonomi_asean.png'),
(225, 'Wakil PBB', 'Wakil yang berucap di dewan sidang PBB (watak rekaan).', 'Menerangkan latar PBB dan sumbangan Malaysia.', 'wakil_pbb(un).png'),
(226, 'Utusan Komanwel', 'Utusan yang membawa berita daripada pertubuhan Komanwel (watak rekaan).', 'Menerangkan latar Komanwel dan sumbangan Malaysia.', 'utusan_komanwel.png'),
(227, 'Wakil OIC', 'Wakil yang menghadiri persidangan negara Islam (watak rekaan).', 'Menerangkan latar OIC dan sumbangan Malaysia.', 'wakil_oic.png'),
(228, 'Duta NAM', 'Duta yang mewakili negara-negara berkecuali (watak rekaan).', 'Menerangkan Pergerakan Negara-negara Berkecuali.', 'duta_nam.png'),
(229, 'Sukarelawan Kemanusiaan OIC', 'Sukarelawan yang membantu mangsa konflik (watak rekaan).', 'Menceritakan sumbangan Malaysia dalam OIC.', 'sukarelawan_kemanusiaan_OIC.png'),
(230, 'Tunku Abdul Rahman', 'Dilantik sebagai Setiausaha Agung pertama OIC.', 'Setiausaha Agung pertama OIC.', 'tunku_abdul_rahman.png'),
(231, 'Wakil Indonesia', 'Wakil yang menyambut tetamu di ibu pejabat ASEAN di Jakarta (watak rekaan).', 'Menyambut tetamu sidang serantau.', 'wakil_indonesia.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(1001, 'Sidang Serantau Wakil Muda ASEAN', 10, 'Masuki peranan wakil muda ASEAN yang menghadiri sidang di bilik mesyuarat dunia. Kau mengenali pertubuhan serantau yang disertai Malaysia dan sumbangan Malaysia dalam ASEAN.'),
(1002, 'Rondaan Keamanan Penjaga Topi Biru', 10, 'Masuki peranan penjaga keamanan PBB yang meronda dari bilik mesyuarat ke bilik mesyuarat. Kau mengenali PBB, Komanwel, NAM dan OIC serta sumbangan Malaysia di setiap pertubuhan.'),
(1003, 'Lawatan Pameran Malaysia dan Dunia', 10, 'Masuki peranan pemandu pameran UNESCO yang membawa pelawat melawat bilik demi bilik. Kau mengenali sumbangan Malaysia dalam PBB, pengiktirafan PBB dan UNESCO serta nilai menjaga hubungan baik.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e10_n1_s1', 'Bilik pendaftaran sidang. Tiga lencana pertubuhan serantau bertukar tempat di atas meja. Wakil Indonesia ragu sama ada Malaysia menyertai ketiga-tiganya.', 1, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s2', 'Peta besar ASEAN di dinding sidang. Sepuluh bendera belum diletakkan mengikut tahun kemasukan. Wakil Indonesia meminta bantuan menyusunnya.', 2, 1001, 'bilik_mesyuarat_dunia.png'),
('e10_n1_s3', 'Bilik mesyuarat Menteri Luar ASEAN. Malaysia pernah menjadi tuan rumah mesyuarat ini. Wakil Indonesia mahu empat bukti keanggotaan ASEAN dalam gambar.', 3, 1001, 'bilik_mesyuarat.png'),
('e10_n1_s4', 'Papan latar belakang ASEAN di lobi. Kad tarikh, bilangan anggota dan ibu pejabat tertukar. Seorang wakil baharu bertanya fakta asas ASEAN.', 4, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s5', 'Dokumen matlamat penubuhan ASEAN di meja. Empat matlamat tertulis tetapi tidak dipadankan dengan butirannya. Pakar ekonomi meminta bantuan.', 5, 1001, 'bilik_mesyuarat_formal.png'),
('e10_n1_s6', 'Lobi dengan bendera ASEAN. Kanak-kanak menunjuk logo dan bertanya tentang warna dan lambangnya. Wakil muda perlu menjawab dengan tepat.', 6, 1001, 'bilik_mesyuarat_modern.png'),
('e10_n1_s7', 'Papan faedah penyertaan Malaysia dalam ASEAN. Kad bercampur antara faedah dan tempat. Wakil muda perlu menyusunnya.', 7, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n1_s8', 'Sidang penutup ASEAN. Wakil dari negara lain bertanya apa sumbangan Malaysia. Dokumen sumbangan tertukar dengan sumbangan organisasi lain.', 8, 1001, 'malaysia_dan_dunia_serantau.png'),
('e10_n2_s1', 'Dewan sidang PBB. Peta dunia di skrin besar menunjukkan kawasan tugas pasukan pengaman. Wakil PBB mahu kau menunjukkan bukti Malaysia terlibat.', 1, 1002, 'malaysia_di_pentas_dunia.png'),
('e10_n2_s2', 'Penyata latar belakang PBB di bilik mesyuarat. Seorang wakil baharu mengelirukan PBB dengan pertubuhan lain. Kad latar belakang bercampur.', 2, 1002, 'bilik_mesyuarat_dunia.png'),
('e10_n2_s3', 'Papan empat pertubuhan antarabangsa. Kad tahun dan bilangan anggota bertukar. Penjaga keamanan perlu memadankannya sebelum mesyuarat bermula.', 3, 1002, 'malaysia_di_pentas_dunia.png'),
('e10_n2_s4', 'Bilik mesyuarat gaya London. Utusan Komanwel menunjukkan dokumen tetapi sebahagian kata terpadam. Kau perlu membaca latar belakang Komanwel.', 4, 1002, 'bilik_mesyuarat_london.png'),
('e10_n2_s5', 'Papan faedah Komanwel. Empat bidang tertulis tetapi butiran tertukar. Utusan Komanwel meminta bantuan menyusunnya.', 5, 1002, 'bilik_mesyuarat_london.png'),
('e10_n2_s6', 'Sidang Komanwel di bilik formal. Tiga sumbangan Malaysia tercatat pada kertas yang basah. Kau perlu menentukan butiran yang betul.', 6, 1002, 'bilik_mesyuarat_formal.png'),
('e10_n2_s7', 'Bilik mesyuarat OIC. Gambar Tunku Abdul Rahman tergantung di dinding. Wakil OIC bertanya jawatan beliau dalam OIC dan kad butiran latar OIC tertukar.', 7, 1002, 'bilik_mesyuarat_modern.png'),
('e10_n2_s8', 'Sukarelawan OIC menyusun fail sumbangan Malaysia. Kad sumbangan tertukar. Wakil OIC meminta kau memadankannya sebelum laporan tahunan.', 8, 1002, 'malaysia_di_pentas_dunia.png'),
('e10_n3_s1', 'Bilik pertama pameran memaparkan peta misi pasukan pengaman PBB. Tujuh kad tarikh dan tempat bertaburan. Pelawat mahu urutan misi mengikut tahun.', 1, 1003, 'bilik_UNMM.png'),
('e10_n3_s2', 'Bilik sumbangan Malaysia dalam PBB. Empat kad besar tergantung senget. Pelawat mahu memahami empat sumbangan lain di luar misi pengaman.', 2, 1003, 'bilik_mesyuarat_dunia.png'),
('e10_n3_s3', 'Bilik faedah PBB. Pelawat bertanya apa faedah negara menyertai PBB. Kad butiran tertukar dengan faedah ASEAN.', 3, 1003, 'bilik_mesyuarat_formal.png'),
('e10_n3_s4', 'Bilik individu Malaysia berpengaruh di PBB. Dua gambar tokoh tergantung terbalik. Pelawat mahu jawatan setiap tokoh dipadankan.', 4, 1003, 'malaysia_di_pentas_dunia.png'),
('e10_n3_s5', 'Ruang UNESCO dengan peta bandar dan gua dalam kaca. Pelawat tidak pasti lokasi warisan dunia Malaysia. Pemandu perlu membimbing mereka.', 5, 1003, 'ruang_unesco.png'),
('e10_n3_s6', 'Empat almari kaca UNESCO. Pelawat keliru antara kategori pengiktirafan. Kad kategori dan contoh bertukar tempat.', 6, 1003, 'ruang_unesco.png'),
('e10_n3_s7', 'Dinding garis masa UNESCO. Lapan pengiktirafan tertulis tanpa tahun yang betul. Pelawat meminta pemandu menyusunnya.', 7, 1003, 'ruang_unesco.png'),
('e10_n3_s8', 'Bilik kepentingan hubungan baik. Pelawat bertanya mengapa Malaysia menjalin hubungan baik dengan negara luar. Kad jawapan bertukar tempat.', 8, 1003, 'bilik_mesyuarat_dunia.png'),
('e10_n3_s9', 'Bilik terakhir pameran. Pelawat diminta menulis cinta akan negara pada tiga peringkat, iaitu diri, masyarakat dan negara.', 9, 1003, 'malaysia_dan_dunia_serantau.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(1001, 'e10_n1_s1', 'Tiga Pertubuhan Serantau', 'Padankan pertubuhan serantau dengan tahun penyertaan dan anggotanya.', '4', 'Memahami pertubuhan serantau: SEAFET (1959), ASA (1961) dan ASEAN (1967).', '{"pairs": [{"text": "SEAFET, 1959", "pair": 1}, {"text": "Persekutuan Tanah Melayu, Thailand dan Filipina", "pair": 1}, {"text": "ASA, 1961", "pair": 2}, {"text": "Persekutuan Tanah Melayu, Thailand dan Filipina juga", "pair": 2}, {"text": "ASEAN, 1967", "pair": 3}, {"text": "Pada awalnya lima buah negara", "pair": 3}], "aftermath": "Lencana bertukar dan wakil Indonesia menyangka Malaysia menyertai ASEAN pada tahun 1959.", "turns": [{"after": 5, "options": [{"text": "Negara berjiran bekerjasama untuk memelihara keharmonian dan kesejahteraan.", "isCorrect": true, "reaction": "Betul. Sidang bermula."}, {"text": "Aku fikir negara berjiran bersaing tanpa kerjasama, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Wakil Indonesia menggeleng. Pertubuhan serantau bertujuan kerjasama."}, {"text": "Pada pendapat aku, pertubuhan serantau menyatukan negara dari benua yang berbeza.", "isCorrect": false, "reaction": "Pertubuhan serantau dianggotai negara berjiran."}], "clue": "Pertubuhan serantau: negara berjiran."}]}'),
(1002, 'e10_n1_s2', 'Pertumbuhan Anggota ASEAN', 'Susun peristiwa penting pertumbuhan ASEAN mengikut urutan.', '1', 'Menyusun kronologi: SEAFET 1959, ASA 1961, ASEAN 1967, Brunei 1984, Vietnam 1995, Laos dan Myanmar 1997, Kemboja 1999.', '{"timelineItems": [{"id": 1, "year": "1959", "text": "Malaysia menyertai SEAFET", "why": "Pertubuhan serantau pertama."}, {"id": 2, "year": "1961", "text": "Persekutuan Tanah Melayu menyertai ASA", "why": "Pertubuhan serantau kedua."}, {"id": 3, "year": "1967", "text": "ASEAN ditubuhkan dengan lima negara awal", "why": "Ditubuhkan pada 8 Ogos 1967."}, {"id": 4, "year": "1984", "text": "Brunei menyertai ASEAN", "why": "Anggota baharu pertama."}, {"id": 5, "year": "1995", "text": "Vietnam menyertai ASEAN", "why": "Anggota baharu kedua."}, {"id": 6, "year": "1997", "text": "Laos dan Myanmar menyertai ASEAN", "why": "Dua anggota serentak."}, {"id": 7, "year": "1999", "text": "Kemboja menyertai ASEAN", "why": "Menjadikan sepuluh negara anggota."}], "aftermath": "Susunan tersilap dan peta ASEAN mencatat Kemboja menyertai sebelum Vietnam.", "turns": [{"after": 6, "options": [{"text": "Anggota bertambah supaya kerjasama serantau lebih luas.", "isCorrect": true, "reaction": "Betul. Sidang berjalan lancar."}, {"text": "Menurut aku, anggota bertambah kerana peperangan.", "isCorrect": false, "reaction": "Wakil Indonesia membetulkan. Ia tentang kerjasama."}, {"text": "ASEAN dianggotai dua puluh negara, jadi lupakan sahaja.", "isCorrect": false, "reaction": "ASEAN kini dianggotai 10 negara."}], "clue": "Anggota bertambah, kerjasama meluas."}]}'),
(1003, 'e10_n1_s3', 'Cari Bukti ASEAN', 'Cari empat bukti kerjasama ASEAN dalam bilik mesyuarat.', '2', 'Memahami ASEAN: Malaysia tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN; sepuluh negara Asia Tenggara; Singapura antara negara awal; matlamat keamanan dan kestabilan politik.', '{"bgImage": "../assets/gameAsset/background/bilik_mesyuarat.png", "hotspots": [{"name": "Bendera Malaysia: tuan rumah Mesyuarat Menteri Luar ASEAN", "top": "44.2%", "left": "27.2%"}, {"name": "Peta Asia Tenggara: ASEAN dianggotai 10 negara Asia Tenggara", "top": "21.3%", "left": "25.5%"}, {"name": "Bendera Singapura: salah satu negara awal ASEAN", "top": "46.6%", "left": "72.2%"}, {"name": "Dokumen perjanjian: matlamat keamanan dan kestabilan politik", "top": "81.3%", "left": "24.4%"}], "aftermath": "Bukti tidak ditemui dan wakil Indonesia menyangka Malaysia tidak aktif dalam ASEAN.", "turns": [{"after": 5, "options": [{"text": "Kerjasama serantau menjamin keamanan dan kestabilan politik.", "isCorrect": true, "reaction": "Betul. Bilik mesyuarat sunyi mendengar."}, {"text": "Aku fikir kerjasama serantau menyebabkan pergolakan.", "isCorrect": false, "reaction": "Dokumen perjanjian menekankan keamanan."}, {"text": "Bagi aku, kerjasama serantau hanya melibatkan satu negara.", "isCorrect": false, "reaction": "Peta menunjukkan sepuluh negara."}], "clue": "Kerjasama menjamin keamanan."}]}'),
(1004, 'e10_n1_s4', 'Kad Latar Belakang ASEAN', 'Baca kad dan tentukan latar belakang ASEAN.', '5', 'Memahami latar ASEAN: ditubuhkan 8 Ogos 1967; kini 10 negara Asia Tenggara; ibu pejabat di Jakarta, Indonesia.', '{"clueText": "Kad: ASEAN ditubuhkan pada 8 Ogos 1967 dan kini dianggotai oleh 10 buah negara Asia Tenggara. Ibu pejabat ASEAN terletak di Jakarta, Indonesia.", "options": [{"text": "Ditubuhkan 8 Ogos 1967; 10 negara; ibu pejabat di Jakarta.", "isCorrect": true}, {"text": "Ditubuhkan 31 Ogos 1957; 5 negara; ibu pejabat di Kuala Lumpur.", "isCorrect": false, "consequence": "31 Ogos 1957 ialah tarikh kemerdekaan Tanah Melayu."}, {"text": "Ditubuhkan 16 September 1963; 12 negara; ibu pejabat di Manila.", "isCorrect": false, "consequence": "Itu tarikh pembentukan Malaysia."}, {"text": "Ditubuhkan 24 Oktober 1945; 193 negara; ibu pejabat di New York.", "isCorrect": false, "consequence": "Itu latar belakang PBB."}], "aftermath": "Kad tersalah baca dan wakil baharu menulis ibu pejabat ASEAN di Kuala Lumpur.", "turns": [{"after": 5, "options": [{"text": "Malaysia ialah antara negara perintis penubuhan ASEAN.", "isCorrect": true, "reaction": "Betul. Wakil baharu mengangguk."}, {"text": "Malaysia menyertai ASEAN selepas tahun 2000, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Malaysia ialah negara perintis tahun 1967."}, {"text": "Aku fikir malaysia tidak terlibat dalam penubuhan ASEAN.", "isCorrect": false, "reaction": "Malaysia ialah antara negara perintis."}], "clue": "Malaysia: negara perintis ASEAN."}]}'),
(1005, 'e10_n1_s5', 'Empat Matlamat ASEAN', 'Padankan matlamat penubuhan ASEAN dengan penerangannya.', '4', 'Memahami matlamat ASEAN: keamanan dan kestabilan politik; pertumbuhan ekonomi, kemajuan sosial dan pembangunan kebudayaan; kerjasama latihan dan penyelidikan; meningkatkan taraf hidup penduduk.', '{"pairs": [{"text": "Keamanan", "pair": 1}, {"text": "Menjamin keamanan dan kestabilan politik", "pair": 1}, {"text": "Pertumbuhan", "pair": 2}, {"text": "Menggalakkan pertumbuhan ekonomi, kemajuan sosial dan pembangunan kebudayaan", "pair": 2}, {"text": "Kerjasama", "pair": 3}, {"text": "Menjalin kerjasama dalam bidang latihan dan penyelidikan", "pair": 3}, {"text": "Kesejahteraan", "pair": 4}, {"text": "Meningkatkan taraf hidup penduduk", "pair": 4}], "aftermath": "Matlamat bertukar dan laporan menyatakan ASEAN ditubuhkan untuk berperang. Pakar ekonomi tersentak.", "turns": [{"after": 5, "options": [{"text": "Hubungan baik dengan jiran memberi faedah yang dikongsi bersama.", "isCorrect": true, "reaction": "Betul. Laporan diterima."}, {"text": "Hubungan baik dengan jiran tidak penting, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Pakar ekonomi menggeleng. Faedahnya dikongsi bersama."}, {"text": "ASEAN ditubuhkan untuk mengasingkan negara anggota, jadi lupakan sahaja.", "isCorrect": false, "reaction": "ASEAN ditubuhkan untuk kerjasama."}], "clue": "Hubungan baik memberi faedah bersama."}]}'),
(1006, 'e10_n1_s6', 'Makna Logo ASEAN', 'Padankan unsur logo ASEAN dengan maknanya.', '4', 'Memahami makna logo: biru (keamanan dan kestabilan), merah (semangat dan dinamisme), kuning (kemakmuran), putih (kesucian), sepuluh tangkai padi (impian pengasasan diikat persahabatan dan perpaduan 10 negara), bulatan (kesatuan).', '{"pairs": [{"text": "Warna biru", "pair": 1}, {"text": "Keamanan dan kestabilan", "pair": 1}, {"text": "Warna merah", "pair": 2}, {"text": "Semangat dan dinamisme", "pair": 2}, {"text": "Warna kuning", "pair": 3}, {"text": "Kemakmuran", "pair": 3}, {"text": "Warna putih", "pair": 4}, {"text": "Kesucian", "pair": 4}, {"text": "Sepuluh tangkai padi", "pair": 5}, {"text": "Impian pengasasan ASEAN diikat persahabatan dan perpaduan", "pair": 5}, {"text": "Bulatan", "pair": 6}, {"text": "Kesatuan ASEAN", "pair": 6}], "aftermath": "Makna bertukar dan kanak-kanak menyangka warna merah melambangkan kemakmuran.", "turns": [{"after": 5, "options": [{"text": "Logo itu mengingatkan kita kepada perpaduan sepuluh negara.", "isCorrect": true, "reaction": "Betul. Kanak-kanak tersenyum."}, {"text": "Logo itu hanya hiasan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Setiap unsur ada makna."}, {"text": "Bagi aku, logo itu lambang satu negara sahaja.", "isCorrect": false, "reaction": "Ia lambang sepuluh negara anggota."}], "clue": "Logo melambangkan perpaduan."}]}'),
(1007, 'e10_n1_s7', 'Faedah Penyertaan dalam ASEAN', 'Padankan faedah penyertaan Malaysia dalam ASEAN dengan butirannya.', '4', 'Memahami faedah: Deklarasi Kuala Lumpur 1971 (ZOPFAN) mengelakkan campur tangan kuasa luar; projek baja urea di Bintulu; Sukan SEA; RECSAM di Pulau Pinang.', '{"pairs": [{"text": "Keamanan dan kestabilan politik", "pair": 1}, {"text": "Deklarasi Kuala Lumpur 1971 mengisytiharkan ZOPFAN", "pair": 1}, {"text": "Pertumbuhan ekonomi", "pair": 2}, {"text": "Projek perindustrian baja urea di Bintulu, Sarawak", "pair": 2}, {"text": "Pertumbuhan sosial", "pair": 3}, {"text": "Menjadi tuan rumah penganjuran Sukan SEA", "pair": 3}, {"text": "Latihan dan penyelidikan", "pair": 4}, {"text": "Pembinaan RECSAM di Pulau Pinang", "pair": 4}], "aftermath": "Kad bertukar dan wakil muda mencatat RECSAM dibina di Sarawak.", "turns": [{"after": 5, "options": [{"text": "Faedah ASEAN dikongsi bersama negara anggota.", "isCorrect": true, "reaction": "Betul. Wakil Indonesia bersetuju."}, {"text": "Faedah ASEAN hanya untuk Malaysia, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Faedah dikongsi bersama."}, {"text": "Faedah ASEAN tiada kaitan dengan rakyat.", "isCorrect": false, "reaction": "Ia meningkatkan taraf hidup penduduk."}], "clue": "Faedah dikongsi bersama."}]}'),
(1008, 'e10_n1_s8', 'Dokumen Sumbangan Malaysia dalam ASEAN', 'Baca dokumen dan tentukan sumbangan Malaysia dalam ASEAN.', '5', 'Memahami sumbangan: tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN; menangani pencerobohan Vietnam ke atas Kemboja; meredakan konflik di selatan Filipina; mengutarakan ZOPFAN; menyertai SEAMEO.', '{"clueText": "Dokumen: Malaysia menjadi tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN, membantu menangani isu pencerobohan Vietnam terhadap Kemboja, membantu meredakan konflik politik di selatan Filipina, mengutarakan penubuhan ZOPFAN dan menyertai Pertubuhan Menteri-Menteri Pelajaran ASEAN (SEAMEO).", "options": [{"text": "Mengutarakan ZOPFAN dan membantu meredakan konflik di selatan Filipina.", "isCorrect": true}, {"text": "Menubuhkan Bank Pembangunan Islam dan UIAM.", "isCorrect": false, "consequence": "Itu sumbangan dalam OIC."}, {"text": "Menamatkan Aparteid dan mengisytiharkan Deklarasi Langkawi.", "isCorrect": false, "consequence": "Itu sumbangan dalam Komanwel."}, {"text": "Menghantar pasukan pengaman ke Congo dan Namibia.", "isCorrect": false, "consequence": "Itu sumbangan dalam PBB."}], "aftermath": "Dokumen tersalah baca dan wakil sidang mencatat sumbangan Malaysia dalam pertubuhan yang salah.", "turns": [{"after": 5, "options": [{"text": "Pelibatan Malaysia dalam ASEAN amat dihargai oleh negara anggota.", "isCorrect": true, "reaction": "Betul. Sidang berakhir dengan tepukan."}, {"text": "Malaysia tidak memberi sumbangan dalam ASEAN, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Dokumen menyenaraikan banyak sumbangan."}, {"text": "Sumbangan Malaysia tidak dihargai, jadi tidak perlu bersusah payah.", "isCorrect": false, "reaction": "Pelibatan Malaysia amat dihargai."}], "clue": "Sumbangan Malaysia dihargai."}]}'),
(1009, 'e10_n2_s1', 'Cari Bukti Malaysia di PBB', 'Cari empat bukti penglibatan Malaysia dalam PBB.', '2', 'Memahami PBB: keahlian terbuka kepada semua negara; Malaysia anggota yang aktif menyumbang; Malaysia menghantar pasukan pengaman PBB.', '{"bgImage": "../assets/gameAsset/background/malaysia_di_pentas_dunia.png", "hotspots": [{"name": "Dewan sidang: keahlian PBB terbuka kepada semua negara", "top": "42.2%", "left": "26.9%"}, {"name": "Bendera Malaysia: negara anggota PBB yang aktif menyumbang", "top": "25.6%", "left": "26.5%"}, {"name": "Peta dunia di skrin: pasukan pengaman PBB termasuk Malaysia", "top": "22.3%", "left": "92.5%"}, {"name": "Peta di skrin utama: kawasan tugas pasukan pengaman PBB", "top": "73.6%", "left": "49.5%"}], "aftermath": "Bukti tidak ditemui dan wakil PBB menyangka Malaysia tidak terlibat dalam misi pengaman.", "turns": [{"after": 5, "options": [{"text": "Pasukan pengaman menjaga keamanan dunia.", "isCorrect": true, "reaction": "Betul. Wakil PBB mengangguk."}, {"text": "Rasanya, pasukan pengaman hanya hiasan.", "isCorrect": false, "reaction": "Penjaga keamanan menegur. Mereka bertugas di kawasan konflik."}, {"text": "Hanya negara besar boleh menjadi anggota PBB.", "isCorrect": false, "reaction": "Keahlian PBB terbuka kepada semua negara."}], "clue": "Pasukan pengaman menjaga keamanan."}]}'),
(1010, 'e10_n2_s2', 'Kad Latar Belakang PBB', 'Baca kad dan tentukan latar belakang PBB.', '5', 'Memahami PBB: ditubuhkan 24 Oktober 1945 selepas Perang Dunia Kedua; keahlian terbuka kepada semua negara; ibu pejabat di New York; enam bahasa rasmi.', '{"clueText": "Kad: Pertubuhan Bangsa-Bangsa Bersatu (PBB) ditubuhkan pada 24 Oktober 1945 selepas Perang Dunia Kedua. Keahliannya terbuka kepada semua negara di seluruh dunia. Ibu pejabat PBB terletak di New York, Amerika Syarikat dan bahasa rasminya ialah bahasa Arab, Mandarin, Inggeris, Perancis, Rusia dan Sepanyol.", "options": [{"text": "Ditubuhkan 24 Oktober 1945; ibu pejabat di New York; enam bahasa rasmi.", "isCorrect": true}, {"text": "Ditubuhkan 8 Ogos 1967; ibu pejabat di Jakarta; satu bahasa rasmi.", "isCorrect": false, "consequence": "Itu maklumat ASEAN."}, {"text": "Ditubuhkan 25 September 1969; ibu pejabat di Jeddah; tiga bahasa rasmi.", "isCorrect": false, "consequence": "Itu maklumat OIC."}, {"text": "Ditubuhkan 11 Disember 1931; ibu pejabat di London; dua bahasa rasmi.", "isCorrect": false, "consequence": "Itu maklumat Komanwel."}], "aftermath": "Kad tersalah baca dan wakil baharu menyangka ibu pejabat PBB di Jeddah.", "turns": [{"after": 5, "options": [{"text": "PBB menjamin keamanan dan keselamatan dunia.", "isCorrect": true, "reaction": "Betul. Wakil baharu mencatat."}, {"text": "PBB hanya untuk negara Asia, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Keahlian PBB terbuka kepada semua negara."}, {"text": "PBB ditubuhkan sebelum Perang Dunia Kedua.", "isCorrect": false, "reaction": "Ia ditubuhkan selepas perang."}], "clue": "PBB menjamin keamanan dunia."}]}'),
(1011, 'e10_n2_s3', 'Pertubuhan Antarabangsa Malaysia', 'Padankan pertubuhan antarabangsa dengan tahun penyertaan dan cirinya.', '4', 'Memahami: Komanwel (1957, bekas tanah jajahan British), PBB (1957, terbuka kepada semua negara), NAM (sejak 1970, 120 negara membangun), OIC (sejak penubuhan 1969, 57 negara).', '{"pairs": [{"text": "Komanwel", "pair": 1}, {"text": "Disertai 1957; anggota bekas tanah jajahan British", "pair": 1}, {"text": "PBB", "pair": 2}, {"text": "Disertai 1957; keahlian terbuka kepada semua negara", "pair": 2}, {"text": "NAM", "pair": 3}, {"text": "Disertai sejak 1970; 120 negara membangun Asia, Afrika, Amerika Selatan", "pair": 3}, {"text": "OIC", "pair": 4}, {"text": "Disertai sejak penubuhannya 1969; awalnya 57 negara", "pair": 4}], "aftermath": "Maklumat bertukar dan mesyuarat bermula dengan nota yang salah tentang NAM.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, malaysia mengamalkan dasar berbaik-baik dengan semua negara.", "isCorrect": true, "reaction": "Betul. Mesyuarat bermula."}, {"text": "Sebenarnya, malaysia mengasingkan diri daripada dunia, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Penjaga keamanan menggeleng. Malaysia menganggotai banyak pertubuhan."}, {"text": "Malaysia menjalin hubungan diplomatik dengan semua negara tanpa pengecualian.", "isCorrect": false, "reaction": "Malaysia tidak mengadakan hubungan diplomatik dengan Israel dan Korea Utara."}], "clue": "Dasar berbaik-baik dengan negara luar."}]}'),
(1012, 'e10_n2_s4', 'Dokumen Latar Belakang Komanwel', 'Baca dokumen dan tentukan latar belakang Komanwel.', '5', 'Memahami Komanwel: dibentuk 11 Disember 1931; 54 negara bekas tanah jajahan British kecuali Mozambique dan Rwanda; Sekretariat di London; matlamat setia kawan dan kerjasama.', '{"clueText": "Dokumen: Komanwel dibentuk pada 11 Disember 1931 dan dianggotai oleh 54 buah negara bekas tanah jajahan British kecuali Mozambique dan Republik Rwanda. Ibu pejabat Sekretariat Komanwel terletak di London, England. Matlamatnya membina semangat setia kawan dan mewujudkan kerjasama dalam pendidikan, ekonomi, kesihatan serta belia dan sukan.", "options": [{"text": "Dibentuk 1931; 54 negara; Sekretariat di London.", "isCorrect": true}, {"text": "Dibentuk 1945; 193 negara; Sekretariat di New York.", "isCorrect": false, "consequence": "Itu maklumat PBB."}, {"text": "Dibentuk 1967; 10 negara; Sekretariat di Jakarta.", "isCorrect": false, "consequence": "Itu maklumat ASEAN."}, {"text": "Dibentuk 1969; 57 negara; Sekretariat di Jeddah.", "isCorrect": false, "consequence": "Itu maklumat OIC."}], "aftermath": "Dokumen tersalah baca dan utusan menyangka Komanwel dibentuk selepas Perang Dunia Kedua.", "turns": [{"after": 5, "options": [{"text": "Bagi aku, komanwel membina semangat setia kawan antara negara anggota.", "isCorrect": true, "reaction": "Betul. Utusan Komanwel tersenyum."}, {"text": "Sebenarnya, komanwel dianggotai semua negara tanpa pengecualian.", "isCorrect": false, "reaction": "Hanya bekas tanah jajahan British (kecuali dua)."}, {"text": "Komanwel ditubuhkan untuk berperang, kerana itu lebih mudah dan cepat.", "isCorrect": false, "reaction": "Komanwel membina setia kawan."}], "clue": "Komanwel: setia kawan."}]}'),
(1013, 'e10_n2_s5', 'Faedah Penyertaan dalam Komanwel', 'Padankan bidang dengan faedah penyertaan Malaysia dalam Komanwel.', '4', 'Memahami faedah Komanwel: pendidikan (biasiswa Komanwel), perdagangan (barangan menembusi pasaran), kesihatan (berkongsi data menangani wabak COVID-19), belia dan sukan (Sukan Komanwel 1998).', '{"pairs": [{"text": "Pendidikan", "pair": 1}, {"text": "Tawaran biasiswa Komanwel untuk melanjutkan pendidikan tinggi", "pair": 1}, {"text": "Perdagangan", "pair": 2}, {"text": "Memudahkan barangan Malaysia menembusi pasaran antarabangsa", "pair": 2}, {"text": "Kesihatan", "pair": 3}, {"text": "Berkongsi maklumat dan data untuk menangani wabak seperti COVID-19", "pair": 3}, {"text": "Belia dan sukan", "pair": 4}, {"text": "Penganjuran Sukan Komanwel pada tahun 1998", "pair": 4}], "aftermath": "Bidang bertukar dan utusan mencatat biasiswa Komanwel sebagai faedah perdagangan.", "turns": [{"after": 5, "options": [{"text": "Komanwel memberi peluang kerjasama kepada pelbagai bidang.", "isCorrect": true, "reaction": "Betul. Utusan menutup fail."}, {"text": "Rasanya, komanwel hanya memberi faedah kepada sukan.", "isCorrect": false, "reaction": "Faedahnya pelbagai bidang."}, {"text": "Komanwel tidak berguna kepada pelajar, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Biasiswa Komanwel membantu pelajar."}], "clue": "Komanwel: faedah pelbagai bidang."}]}'),
(1014, 'e10_n2_s6', 'Nota Sumbangan Malaysia dalam Komanwel', 'Baca nota dan tentukan sumbangan Malaysia dalam Komanwel.', '5', 'Memahami sumbangan: mengecam Aparteid di Afrika Selatan; membantu menamatkannya 1993; tuan rumah CHOGM 1989; Deklarasi Langkawi 1989 (pencemaran alam sekitar).', '{"clueText": "Nota: Malaysia mengecam dasar Aparteid di Afrika Selatan yang membezakan penduduk mengikut warna kulit dan membantu menamatkannya pada tahun 1993. Malaysia menjadi tuan rumah Commonwealth Heads of Government Meeting (CHOGM) pada tahun 1989 dan mengisytiharkan Deklarasi Langkawi 1989 tentang pencemaran alam sekitar.", "options": [{"text": "Menamatkan Aparteid 1993 dan Deklarasi Langkawi 1989.", "isCorrect": true}, {"text": "Mengutarakan ZOPFAN dan menyertai SEAMEO.", "isCorrect": false, "consequence": "Itu sumbangan dalam ASEAN."}, {"text": "Menubuhkan Bank Pembangunan Islam dan UIAM.", "isCorrect": false, "consequence": "Itu sumbangan dalam OIC."}, {"text": "Menghantar pasukan pengaman ke Namibia.", "isCorrect": false, "consequence": "Itu sumbangan dalam PBB."}], "aftermath": "Nota tersalah baca dan utusan menyatakan Aparteid ditamatkan pada tahun 1989.", "turns": [{"after": 5, "options": [{"text": "Malaysia mengecam ketidakadilan dan memelihara alam sekitar.", "isCorrect": true, "reaction": "Betul. Utusan mengangguk."}, {"text": "Malaysia menyokong dasar Aparteid, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Malaysia mengecam dasar itu."}, {"text": "Malaysia tidak peduli tentang alam sekitar, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Deklarasi Langkawi berkaitan pencemaran alam sekitar."}], "clue": "Mengecam ketidakadilan."}]}'),
(1015, 'e10_n2_s7', 'Kad Latar Belakang OIC', 'Baca kad dan tentukan latar belakang OIC.', '5', 'Memahami OIC: ditubuhkan 25 September 1969; Tunku Setiausaha Agung pertama; pejabat di Jeddah; 57 negara; bahasa Arab, Inggeris dan Perancis; matlamat memperkukuh perpaduan negara Islam.', '{"clueText": "Kad: OIC ditubuhkan pada 25 September 1969. Tunku Abdul Rahman dilantik sebagai Setiausaha Agung OIC yang pertama. Pejabat OIC terletak di Jeddah, Arab Saudi dan OIC dianggotai 57 buah negara. Bahasa rasminya ialah bahasa Arab, Inggeris dan Perancis.", "options": [{"text": "Setiausaha Agung pertama; pejabat di Jeddah; 57 negara.", "isCorrect": true}, {"text": "Presiden pertama; pejabat di New York; 193 negara.", "isCorrect": false, "consequence": "Itu maklumat PBB."}, {"text": "Pengerusi pertama; pejabat di London; 54 negara.", "isCorrect": false, "consequence": "Itu maklumat Komanwel."}, {"text": "Setiausaha Agung pertama; pejabat di Jakarta; 10 negara.", "isCorrect": false, "consequence": "Itu maklumat ASEAN."}], "aftermath": "Kad tersalah baca dan wakil mencatat Tunku sebagai Presiden PBB.", "turns": [{"after": 5, "options": [{"text": "OIC mengukuhkan perpaduan dan mengeratkan hubungan negara Islam.", "isCorrect": true, "reaction": "Betul. Tunku tersenyum."}, {"text": "OIC hanya untuk negara tertentu di Asia Tenggara, jadi lupakan sahaja.", "isCorrect": false, "reaction": "OIC dianggotai 57 negara."}, {"text": "OIC bertujuan menjejaskan keamanan, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Matlamat OIC mengekalkan keamanan."}], "clue": "OIC: perpaduan negara Islam."}]}'),
(1016, 'e10_n2_s8', 'Sumbangan Malaysia dalam OIC', 'Padankan sumbangan Malaysia dalam OIC dengan butirannya.', '4', 'Memahami sumbangan: Bank Pembangunan Islam 1975; isu Bosnia dan Herzegovina 1991; UIAM 1983; tuan rumah persidangan OIC 1974 dan 2003; menyokong perjuangan rakyat Palestin.', '{"pairs": [{"text": "Membantu penubuhan", "pair": 1}, {"text": "Bank Pembangunan Islam pada tahun 1975", "pair": 1}, {"text": "Menangani isu", "pair": 2}, {"text": "Bosnia dan Herzegovina pada tahun 1991", "pair": 2}, {"text": "Menubuhkan", "pair": 3}, {"text": "Universiti Islam Antarabangsa Malaysia (UIAM) pada tahun 1983", "pair": 3}, {"text": "Menjadi tuan rumah Persidangan OIC", "pair": 4}, {"text": "Tahun 1974 dan 2003", "pair": 4}, {"text": "Menyokong penuh", "pair": 5}, {"text": "Perjuangan rakyat Palestin menentang kekejaman Israel", "pair": 5}], "aftermath": "Kad bertukar dan UIAM dicatat ditubuhkan pada 1975. Wakil OIC menggeleng.", "turns": [{"after": 6, "options": [{"text": "Pelibatan Malaysia dalam OIC penting untuk mengekalkan keamanan dunia.", "isCorrect": true, "reaction": "Betul. Laporan tahunan siap."}, {"text": "Pelibatan Malaysia dalam OIC tidak penting, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Wakil OIC menggeleng."}, {"text": "Pelibatan Malaysia hanya melalui peperangan, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Malaysia mengamalkan rundingan perdamaian."}], "clue": "Rundingan perdamaian mengekalkan keamanan."}]}'),
(1017, 'e10_n3_s1', 'Misi Pasukan Pengaman PBB', 'Susun penglibatan Malaysia dalam PBB mengikut urutan tahun.', '1', 'Menyusun kronologi: Congo (1961), ahli tidak tetap Majlis Keselamatan (1965), Namibia (1989), pemerhati Iran-Iraq (1990), Somalia dan Bosnia (1992), Lubnan (2007).', '{"timelineItems": [{"id": 1, "year": "1961", "text": "Malaysia menghantar pasukan pengaman PBB ke Congo", "why": "Misi pengaman pertama."}, {"id": 2, "year": "1965", "text": "Malaysia menjadi ahli tidak tetap Majlis Keselamatan PBB", "why": "Kali pertama daripada empat penggal."}, {"id": 3, "year": "1989", "text": "Malaysia menghantar pasukan pengaman ke Namibia", "why": "Selepas Congo."}, {"id": 4, "year": "1990", "text": "Pasukan pemerhati PBB dihantar ke sempadan Iran-Iraq", "why": "Sebagai pemerhati."}, {"id": 5, "year": "1992", "text": "Pasukan pengaman dihantar ke Somalia dan Bosnia dan Herzegovina", "why": "Dua misi dalam tahun yang sama."}, {"id": 6, "year": "2007", "text": "Pasukan pengaman Malaysia bertugas di Lubnan", "why": "Misi yang terkini dalam unit ini."}], "aftermath": "Urutan tersilap dan pameran mencatat Lubnan sebelum Congo. Pelawat tertawa.", "turns": [{"after": 6, "options": [{"text": "Pasukan pengaman menjaga keamanan dunia dan mengharumkan nama Malaysia.", "isCorrect": true, "reaction": "Betul. Pelawat bertepuk tangan."}, {"text": "Pasukan pengaman bertugas untuk menjajah negara lain, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Itu salah. Mereka menjaga keamanan."}, {"text": "Pada pendapat aku, malaysia tidak pernah menghantar pasukan pengaman.", "isCorrect": false, "reaction": "Banyak misi dalam sejarah."}], "clue": "Pasukan pengaman: keamanan dunia."}]}'),
(1018, 'e10_n3_s2', 'Sumbangan Malaysia dalam PBB', 'Padankan sumbangan Malaysia dalam PBB dengan butirannya.', '4', 'Memahami sumbangan: isu Palestin-Israel; Persidangan Antarabangsa Dadah di Vienna Jun 1987 (Tun Dr. Mahathir Presiden); ''Pendidikan untuk Semua'' melalui UNESCO; ahli tidak tetap Majlis Keselamatan (1965, 1989-1990, 1999-2000, 2015-2016).', '{"pairs": [{"text": "Konflik Palestin-Israel", "pair": 1}, {"text": "Mencari penyelesaian yang adil dan berkekalan", "pair": 1}, {"text": "Penyalahgunaan dadah", "pair": 2}, {"text": "Persidangan Antarabangsa Dadah di Vienna, Jun 1987", "pair": 2}, {"text": "Presiden Persidangan Dadah 1987", "pair": 3}, {"text": "Tun Dr. Mahathir Mohamad, Perdana Menteri keempat", "pair": 3}, {"text": "Mutu pendidikan", "pair": 4}, {"text": "Memperjuangkan prinsip Pendidikan untuk Semua melalui UNESCO", "pair": 4}, {"text": "Majlis Keselamatan PBB", "pair": 5}, {"text": "Ahli tidak tetap 1965, 1989-1990, 1999-2000 dan 2015-2016", "pair": 5}], "aftermath": "Kad bertukar dan pelawat membawa pulang cerita bahawa Tunku mempengerusikan persidangan dadah.", "turns": [{"after": 6, "options": [{"text": "Pandangan Malaysia disuarakan menerusi persidangan PBB.", "isCorrect": true, "reaction": "Betul. Pelawat bersetuju."}, {"text": "Malaysia tidak perlu bersuara di PBB, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Pelawat menggeleng. Pandangan Malaysia disuarakan."}, {"text": "Sumbangan Malaysia hanya melalui ketenteraan, kerana itu lebih senang.", "isCorrect": false, "reaction": "Sumbangan juga dalam pendidikan dan dadah."}], "clue": "Malaysia bersuara di PBB."}]}'),
(1019, 'e10_n3_s3', 'Kad Faedah Penyertaan dalam PBB', 'Baca kad dan tentukan faedah penyertaan Malaysia dalam PBB.', '5', 'Memahami faedah PBB: memelihara dan mempertahankan kepentingan negara dalam keputusan PBB; meneruskan peranan aktif dengan menyumbang pendapat; meningkatkan komitmen menangani isu.', '{"clueText": "Kad: Penyertaan dalam PBB membolehkan Malaysia memelihara dan mempertahankan kepentingan negara dalam sebarang keputusan yang diambil oleh PBB. Malaysia juga meneruskan peranan aktif dengan menyumbang pendapat dan pandangan dalam pelbagai isu global serta meningkatkan komitmen menangani pelbagai isu.", "options": [{"text": "Mempertahankan kepentingan negara dan menyumbang pandangan dalam isu global.", "isCorrect": true}, {"text": "Mendapat pinjaman daripada Bank Pembangunan Islam.", "isCorrect": false, "consequence": "Itu faedah dalam OIC."}, {"text": "Menembusi pasaran negara Komanwel.", "isCorrect": false, "consequence": "Itu faedah dalam Komanwel."}, {"text": "Membina RECSAM di Pulau Pinang.", "isCorrect": false, "consequence": "Itu faedah dalam ASEAN."}], "aftermath": "Kad tersalah baca dan pelawat menyangka PBB memberi pinjaman Bank Pembangunan Islam.", "turns": [{"after": 5, "options": [{"text": "Pelibatan aktif memberi faedah kepada negara dan dunia.", "isCorrect": true, "reaction": "Betul. Pelawat mencatat."}, {"text": "Pelibatan aktif tidak penting kerana negara kecil.", "isCorrect": false, "reaction": "Pelawat menggeleng. Suara Malaysia dihargai."}, {"text": "Pelibatan aktif hanya bertujuan mengejar nama.", "isCorrect": false, "reaction": "Tujuannya menyumbang kepada isu global."}], "clue": "Pelibatan aktif memberi faedah."}]}'),
(1020, 'e10_n3_s4', 'Tokoh Malaysia di PBB', 'Padankan tokoh Malaysia dengan jawatan atau pengiktirafannya di PBB.', '4', 'Memahami pengiktirafan: Tan Sri Razali Ismail (Pengerusi Majlis Keselamatan 1989-1990; Pengerusi Perhimpunan Agung sesi ke-51 1996-1997); Datuk Dr. Mazlan Othman (Pengarah Hal Ehwal Angkasa Lepas PBB 1999-2002 dan 2007); Pasukan Pengaman diiktiraf melalui sijil dan pingat.', '{"pairs": [{"text": "Tan Sri Razali Ismail: 1989-1990", "pair": 1}, {"text": "Pengerusi Majlis Keselamatan PBB", "pair": 1}, {"text": "Tan Sri Razali Ismail: 1996-1997", "pair": 2}, {"text": "Pengerusi Perhimpunan Agung PBB sesi ke-51", "pair": 2}, {"text": "Datuk Dr. Mazlan Othman", "pair": 3}, {"text": "Pengarah Hal Ehwal Angkasa Lepas PBB", "pair": 3}, {"text": "Pasukan Pengaman PBB", "pair": 4}, {"text": "Diiktiraf melalui sijil dan pingat perkhidmatan PBB", "pair": 4}], "aftermath": "Tokoh dipadankan dengan jawatan yang salah dan pameran mencatat Mazlan Othman Pengerusi Majlis Keselamatan.", "turns": [{"after": 5, "options": [{"text": "Pengiktirafan itu perlu dikekalkan demi nama baik negara.", "isCorrect": true, "reaction": "Betul. Pelawat bangga."}, {"text": "Bagi aku, pengiktirafan itu tidak perlu dikekalkan.", "isCorrect": false, "reaction": "Nama baik negara bergantung pada pengiktirafan."}, {"text": "Rasanya, pengiktirafan itu hanya untuk individu, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Ia mengangkat nama Malaysia."}], "clue": "Kekalkan pengiktirafan."}]}'),
(1021, 'e10_n3_s5', 'Cari Bukti Warisan Dunia', 'Cari empat bukti Tapak Warisan Dunia UNESCO di Malaysia.', '2', 'Memahami Tapak Warisan Dunia: alam semula jadi (Taman Negara Gunung Mulu, Taman Kinabalu, 2000) dan kebudayaan (Melaka dan George Town 2008; Lembah Lenggong 2012).', '{"bgImage": "../assets/gameAsset/background/ruang_unesco.png", "hotspots": [{"name": "Gunung dalam kaca: Taman Kinabalu di Sabah, warisan alam 2000", "top": "50%", "left": "8%"}, {"name": "Gua batu kapur: Taman Negara Gunung Mulu di Sarawak, warisan 2000", "top": "52%", "left": "88%"}, {"name": "Peta bandar dalam kaca: Melaka dan George Town, warisan 2008", "top": "56%", "left": "72%"}, {"name": "Hologram tengah: Warisan Arkeologi Lembah Lenggong, 2012", "top": "42%", "left": "50%"}], "aftermath": "Bukti tidak ditemui dan pelawat menyangka Malaysia tiada tapak warisan dunia.", "turns": [{"after": 5, "options": [{"text": "Warisan dunia perlu dipelihara demi generasi akan datang.", "isCorrect": true, "reaction": "Betul. Pelawat bersetuju."}, {"text": "Warisan dunia tidak perlu dipelihara, kerana itu lebih senang.", "isCorrect": false, "reaction": "Pemandu menegur. Ia pengiktirafan antarabangsa."}, {"text": "Warisan dunia hanya milik satu negeri, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Ia warisan negara dan dunia."}], "clue": "Pelihara warisan dunia."}]}'),
(1022, 'e10_n3_s6', 'Kategori Pengiktirafan UNESCO', 'Padankan kategori pengiktirafan UNESCO dengan contohnya.', '4', 'Memahami kategori: Tapak Warisan Dunia Alam Semula Jadi (Mulu, Kinabalu); Tapak Warisan Dunia Kebudayaan (Melaka dan George Town, Lenggong); Daftar Memori Dunia (Hikayat Hang Tuah, Sulalatus Salatin, Batu Bersurat Terengganu); Daftar Warisan Budaya Tidak Ketara (Makyung, Dondang Sayang, Silat, Wangkang).', '{"pairs": [{"text": "Tapak Warisan Dunia Alam Semula Jadi", "pair": 1}, {"text": "Taman Negara Gunung Mulu dan Taman Kinabalu", "pair": 1}, {"text": "Tapak Warisan Dunia Kebudayaan", "pair": 2}, {"text": "Melaka, George Town dan Lembah Lenggong", "pair": 2}, {"text": "Daftar Memori Dunia", "pair": 3}, {"text": "Hikayat Hang Tuah, Sulalatus Salatin dan Batu Bersurat Terengganu", "pair": 3}, {"text": "Daftar Warisan Budaya Tidak Ketara", "pair": 4}, {"text": "Makyung, Dondang Sayang, Silat dan Wangkang", "pair": 4}], "aftermath": "Kategori bertukar dan pelawat menyangka Hikayat Hang Tuah ialah tapak warisan alam.", "turns": [{"after": 5, "options": [{"text": "Pengiktirafan UNESCO menunjukkan warisan Malaysia dihargai dunia.", "isCorrect": true, "reaction": "Betul. Pelawat bangga."}, {"text": "Pengiktirafan UNESCO tidak berkaitan dengan warisan, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Ia mengiktiraf tapak, memori dan budaya."}, {"text": "Hanya bangunan boleh diiktiraf UNESCO, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Manuskrip, tarian dan seni mempertahankan diri turut diiktiraf."}], "clue": "UNESCO menghargai warisan."}]}'),
(1023, 'e10_n3_s7', 'Garis Masa Pengiktirafan UNESCO', 'Susun pengiktirafan UNESCO kepada Malaysia mengikut urutan tahun.', '1', 'Menyusun kronologi: Mulu dan Kinabalu (2000), Hikayat Hang Tuah (2001), Makyung (2005), Melaka dan George Town (2008), Lenggong (2012), Dondang Sayang (2018), Silat (2019), Wangkang (2020).', '{"timelineItems": [{"id": 1, "year": "2000", "text": "Taman Negara Gunung Mulu dan Taman Kinabalu diiktiraf Tapak Warisan Dunia", "why": "Kategori alam semula jadi."}, {"id": 2, "year": "2001", "text": "Hikayat Hang Tuah diiktiraf Daftar Memori Dunia", "why": "Kategori memori dunia."}, {"id": 3, "year": "2005", "text": "Makyung diiktiraf Daftar Warisan Budaya Tidak Ketara", "why": "Kategori warisan tidak ketara."}, {"id": 4, "year": "2008", "text": "Melaka dan George Town diiktiraf Tapak Warisan Dunia kebudayaan", "why": "Bandar bersejarah Selat Melaka."}, {"id": 5, "year": "2012", "text": "Warisan Arkeologi Lembah Lenggong diiktiraf", "why": "Tapak warisan di Perak."}, {"id": 6, "year": "2018", "text": "Dondang Sayang diiktiraf Daftar Warisan Budaya Tidak Ketara", "why": "Seni muzik tradisional."}, {"id": 7, "year": "2019", "text": "Silat diiktiraf Daftar Warisan Budaya Tidak Ketara", "why": "Seni mempertahankan diri."}, {"id": 8, "year": "2020", "text": "Wangkang diiktiraf Daftar Warisan Budaya Tidak Ketara", "why": "Pengiktirafan terkini dalam unit ini."}], "aftermath": "Garis masa tersilap dan pameran mencatat Wangkang diiktiraf sebelum Hikayat Hang Tuah.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, kita perlu berusaha mengekalkan pengiktirafan daripada negara luar.", "isCorrect": true, "reaction": "Betul. Pelawat mengangguk."}, {"text": "Bagi aku, pengiktirafan tidak perlu dikekalkan selepas diterima, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Pengiktirafan perlu dikekalkan."}, {"text": "Menurut aku, pengiktirafan datang tanpa usaha, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Ia hasil sumbangan dan penjagaan warisan."}], "clue": "Kekalkan pengiktirafan."}]}'),
(1024, 'e10_n3_s8', 'Kad Hubungan Baik dengan Negara Luar', 'Baca kad dan tentukan sebab Malaysia menjalin hubungan baik dengan negara luar.', '5', 'Memahami: Malaysia mengamalkan dasar berbaik-baik dengan semua negara; bertanggungjawab memastikan kestabilan politik, kemajuan ekonomi dan keharmonian rakyat; tidak mengadakan hubungan diplomatik dengan Israel dan Korea Utara.', '{"clueText": "Kad: Malaysia mengamalkan dasar berbaik-baik dengan semua negara dan bertanggungjawab memastikan kestabilan politik, kemajuan ekonomi serta keharmonian rakyatnya. Hubungan baik dengan negara luar penting bagi menjamin keselamatan dan kemakmuran rakyat serta negara.", "options": [{"text": "Menjamin keselamatan dan kemakmuran rakyat serta negara.", "isCorrect": true}, {"text": "Menyebabkan negara dipinggirkan.", "isCorrect": false, "consequence": "Kad menyatakan sebaliknya."}, {"text": "Mengurangkan kestabilan politik.", "isCorrect": false, "consequence": "Hubungan baik memastikan kestabilan."}, {"text": "Menjejaskan kemajuan ekonomi.", "isCorrect": false, "consequence": "Hubungan baik menyokong kemajuan ekonomi."}], "aftermath": "Kad tersalah baca dan pelawat menyangka hubungan antarabangsa tidak memberi manfaat.", "turns": [{"after": 5, "options": [{"text": "Hubungan baik menjadikan negara dihormati dan disegani.", "isCorrect": true, "reaction": "Betul. Pelawat tersenyum."}, {"text": "Rasanya, hubungan baik hanya penting untuk negara besar.", "isCorrect": false, "reaction": "Malaysia juga mendapat faedah."}, {"text": "Hubungan baik tidak mempengaruhi keselamatan, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Ia menjamin keselamatan dan kemakmuran."}], "clue": "Hubungan baik: dihormati dan disegani."}]}'),
(1025, 'e10_n3_s9', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan peranannya.', '4', 'Memahami cinta akan negara: diri memelihara hubungan baik dengan jiran; masyarakat membentuk perpaduan dan faedah untuk semua; negara dihormati serta disegani melalui kesepakatan.', '{"pairs": [{"text": "Diri", "pair": 1}, {"text": "Memelihara hubungan baik dengan jiran supaya keharmonian dapat dipupuk", "pair": 1}, {"text": "Masyarakat", "pair": 2}, {"text": "Hubungan baik membentuk perpaduan dan mendatangkan faedah kepada semua", "pair": 2}, {"text": "Negara", "pair": 3}, {"text": "Kesepakatan menjadikan negara dihormati serta disegani", "pair": 3}], "aftermath": "Padanan tersilap dan pelawat pulang tanpa memahami peranan masing-masing.", "turns": [{"after": 5, "options": [{"text": "Pandangan dan sumbangan Malaysia memastikan kesejahteraan dan keamanan dunia.", "isCorrect": true, "reaction": "Betul. Pameran ditutup dengan tepukan."}, {"text": "Hubungan baik tidak perlu dijaga selepas merdeka, kerana itu lebih senang.", "isCorrect": false, "reaction": "Pelibatan bermula sejak merdeka dan perlu dikekalkan."}, {"text": "Hubungan baik hanya urusan kerajaan, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Diri, masyarakat dan negara bertanggungjawab."}], "clue": "Hubungan baik tanggungjawab bersama."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e10_n1_s1', 'hint', 'Persekutuan Tanah Melayu, Thailand dan Filipina menyertai SEAFET dan ASA.', NULL, NULL),
(1001, NULL, 'hint', 'SEAFET 1959. ASA 1961. ASEAN 1967 dengan lima negara pada awalnya.', 'Aku menyusun tiga pertubuhan serantau. SEAFET ditubuhkan pada 1959 dan ASA pada 1961, kedua-duanya dengan Persekutuan Tanah Melayu, Thailand dan Filipina, manakala ASEAN lahir pada 1967 dan pada awalnya dianggotai lima buah negara.', 'Betul! Wakil Muda ASEAN menyalin padanan itu ke dalam nota sidangnya.'),
(NULL, 'e10_n1_s2', 'hint', 'Laos dan Myanmar menyertai serentak pada tahun 1997.', NULL, NULL),
(1002, NULL, 'hint', '1959, 1961, 1967, 1984, 1995, 1997 dan 1999.', 'Aku menyusun pertumbuhan ASEAN. Malaysia menyertai SEAFET pada 1959, ASA pada 1961, ASEAN ditubuhkan pada 1967 dengan lima negara, Brunei menyertai pada 1984, Vietnam pada 1995, Laos dan Myanmar pada 1997 dan Kemboja pada 1999 sehingga menjadi sepuluh negara.', 'Tepat! Peta ASEAN dalam bilik sidang dilengkapkan negara demi negara.'),
(NULL, 'e10_n1_s3', 'hint', 'Dokumen perjanjian menyatakan keamanan dan kestabilan politik.', NULL, NULL),
(1003, NULL, 'hint', 'Empat bukti. Bendera Malaysia, peta Asia Tenggara, bendera Singapura dan dokumen perjanjian.', 'Aku mencari empat bukti ASEAN di bilik sidang. Bendera Malaysia tuan rumah Mesyuarat Menteri Luar ASEAN, peta Asia Tenggara dengan 10 negara anggota, bendera Singapura negara awal ASEAN, dan dokumen perjanjian tentang keamanan dan kestabilan politik.', 'Cekap! Keempat-empat petunjuk dijumpai dan sidang boleh diteruskan.'),
(NULL, 'e10_n1_s4', 'hint', '31 Ogos 1957 ialah kemerdekaan Tanah Melayu.', NULL, NULL),
(1004, NULL, 'hint', '8 Ogos 1967, 10 negara, ibu pejabat di Jakarta.', 'ASEAN ditubuhkan pada 8 Ogos 1967 dan kini dianggotai oleh 10 buah negara Asia Tenggara. Ibu pejabat ASEAN terletak di Jakarta, Indonesia.', 'Betul! Kad yang terkoyak itu kini lengkap semula.'),
(NULL, 'e10_n1_s5', 'hint', 'Kerjasama ialah latihan dan penyelidikan.', NULL, NULL),
(1005, NULL, 'hint', 'Keamanan, pertumbuhan, kerjasama dan kesejahteraan.', 'Aku belajar empat matlamat ASEAN. Keamanan menjamin keamanan dan kestabilan politik, pertumbuhan menggalakkan ekonomi, kemajuan sosial dan kebudayaan, kerjasama dalam latihan dan penyelidikan, dan kesejahteraan meningkatkan taraf hidup penduduk.', 'Tepat! Empat matlamat ASEAN kini tersusun dalam ucapan Wakil Muda.'),
(NULL, 'e10_n1_s6', 'hint', 'Sepuluh tangkai padi diikat persahabatan dan perpaduan.', NULL, NULL),
(1006, NULL, 'hint', 'Biru keamanan, merah semangat, kuning kemakmuran, putih kesucian. Sepuluh tangkai padi dan bulatan.', 'Logo ASEAN ada maknanya. Warna biru melambangkan keamanan dan kestabilan, merah semangat dan dinamisme, kuning kemakmuran, putih kesucian, sepuluh tangkai padi impian pengasasan yang diikat persahabatan dan perpaduan, dan bulatan kesatuan ASEAN.', 'Betul! Wakil Muda tersenyum kerana setiap warna logo kini ada maknanya.'),
(NULL, 'e10_n1_s7', 'hint', 'ZOPFAN diisytiharkan melalui Deklarasi Kuala Lumpur 1971.', NULL, NULL),
(1007, NULL, 'hint', 'ZOPFAN 1971. Baja urea di Bintulu. Sukan SEA. RECSAM di Pulau Pinang.', 'Aku memadankan faedah penyertaan dalam ASEAN. Keamanan dan kestabilan politik dengan Deklarasi Kuala Lumpur 1971 yang mengisytiharkan ZOPFAN, pertumbuhan ekonomi dengan baja urea di Bintulu, pertumbuhan sosial dengan Sukan SEA, dan latihan serta penyelidikan dengan RECSAM di Pulau Pinang.', 'Hebat! Faedah ASEAN itu tersusun dengan buktinya.'),
(NULL, 'e10_n1_s8', 'hint', 'Malaysia juga menyertai SEAMEO.', NULL, NULL),
(1008, NULL, 'hint', 'ZOPFAN dan membantu meredakan konflik di selatan Filipina.', 'Malaysia menjadi tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN, membantu menangani pencerobohan Vietnam terhadap Kemboja, membantu meredakan konflik di selatan Filipina, mengutarakan ZOPFAN dan menyertai SEAMEO.', 'Tepat! Sumbangan Malaysia dalam ASEAN dipisahkan daripada pertubuhan lain.'),
(NULL, 'e10_n2_s1', 'hint', 'Keahlian PBB terbuka kepada semua negara.', NULL, NULL),
(1009, NULL, 'hint', 'Empat bukti. Dewan sidang, bendera Malaysia, peta dunia dan peta di skrin utama.', 'Aku meronda dewan PBB dan mencari empat petunjuk. Dewan sidang tempat keahlian terbuka kepada semua negara, bendera Malaysia negara anggota yang aktif, peta dunia dengan pasukan pengaman termasuk Malaysia, dan peta di skrin utama yang menunjukkan kawasan tugas pasukan pengaman PBB.', 'Cekap! Penjaga Keamanan mengangguk dan topi birunya dibetulkan.'),
(NULL, 'e10_n2_s2', 'hint', 'Bahasa rasmi PBB ialah Arab, Mandarin, Inggeris, Perancis, Rusia dan Sepanyol.', NULL, NULL),
(1010, NULL, 'hint', '24 Oktober 1945, New York, enam bahasa rasmi.', 'PBB ditubuhkan pada 24 Oktober 1945 selepas Perang Dunia Kedua. Keahliannya terbuka kepada semua negara, ibu pejabatnya di New York, Amerika Syarikat, dan ia mempunyai enam bahasa rasmi iaitu Arab, Mandarin, Inggeris, Perancis, Rusia dan Sepanyol.', 'Betul! Wakil baharu tidak lagi keliru tentang PBB.'),
(NULL, 'e10_n2_s3', 'hint', 'NAM dianggotai 120 negara membangun.', NULL, NULL),
(1011, NULL, 'hint', 'Komanwel dan PBB 1957. NAM sejak 1970. OIC sejak penubuhannya 1969.', 'Aku memadankan pertubuhan antarabangsa Malaysia. Komanwel dan PBB disertai pada 1957, NAM sejak 1970 dengan 120 negara membangun dari Asia, Afrika dan Amerika Selatan, dan OIC sejak penubuhannya pada 1969 dengan awalnya 57 negara.', 'Hebat! Utusan dan duta tersenyum kerana pertubuhan itu tidak lagi bercampur.'),
(NULL, 'e10_n2_s4', 'hint', 'Matlamatnya setia kawan dan kerjasama.', NULL, NULL),
(1012, NULL, 'hint', '1931, 54 negara, Sekretariat di London.', 'Komanwel dibentuk pada 11 Disember 1931 dan dianggotai 54 buah negara bekas tanah jajahan British kecuali Mozambique dan Republik Rwanda. Ibu pejabat Sekretariat di London dan matlamatnya membina semangat setia kawan serta kerjasama dalam pendidikan, ekonomi, kesihatan, belia dan sukan.', 'Betul! Dokumen yang luntur itu dibaca semula dengan tepat.'),
(NULL, 'e10_n2_s5', 'hint', 'Sukan Komanwel dianjurkan di Malaysia pada tahun 1998.', NULL, NULL),
(1013, NULL, 'hint', 'Pendidikan dengan biasiswa, perdagangan dengan pasaran, kesihatan dengan data, belia dan sukan dengan 1998.', 'Aku memadankan faedah Komanwel. Pendidikan dengan biasiswa Komanwel, perdagangan dengan pasaran antarabangsa, kesihatan dengan perkongsian data untuk menangani wabak seperti COVID-19, dan belia serta sukan dengan penganjuran Sukan Komanwel pada tahun 1998.', 'Tepat! Faedah Komanwel kini tersusun mengikut bidang.'),
(NULL, 'e10_n2_s6', 'hint', 'CHOGM 1989 diadakan di Malaysia.', NULL, NULL),
(1014, NULL, 'hint', 'Aparteid ditamatkan 1993. Deklarasi Langkawi 1989.', 'Malaysia mengecam dasar Aparteid di Afrika Selatan dan membantu menamatkannya pada 1993. Malaysia juga tuan rumah CHOGM pada 1989 dan mengisytiharkan Deklarasi Langkawi 1989 tentang pencemaran alam sekitar.', 'Betul! Sumbangan Komanwel dan sumbangan pertubuhan lain tidak lagi bercampur.'),
(NULL, 'e10_n2_s7', 'hint', 'Bahasa rasmi OIC ialah Arab, Inggeris dan Perancis.', NULL, NULL),
(1015, NULL, 'hint', 'Setiausaha Agung pertama, pejabat di Jeddah, 57 negara.', 'OIC ditubuhkan pada 25 September 1969 dan Tunku Abdul Rahman dilantik sebagai Setiausaha Agung OIC yang pertama. Pejabat OIC di Jeddah, Arab Saudi, dianggotai 57 buah negara dan bahasa rasminya Arab, Inggeris dan Perancis.', 'Tepat! Tunku Abdul Rahman mengangguk kerana kad OIC itu dipilih dengan betul.'),
(NULL, 'e10_n2_s8', 'hint', 'Malaysia menyokong penuh perjuangan rakyat Palestin.', NULL, NULL),
(1016, NULL, 'hint', 'Bank 1975, Bosnia 1991, UIAM 1983, persidangan 1974 dan 2003, Palestin.', 'Aku menyusun sumbangan Malaysia dalam OIC. Membantu penubuhan Bank Pembangunan Islam pada 1975, menangani isu Bosnia dan Herzegovina pada 1991, menubuhkan UIAM pada 1983, tuan rumah Persidangan OIC pada 1974 dan 2003, dan menyokong penuh perjuangan rakyat Palestin.', 'Betul! Sukarelawan menyimpan senarai sumbangan itu dalam laporan tahunannya.'),
(NULL, 'e10_n3_s1', 'hint', 'Misi pengaman pertama ialah ke Congo pada tahun 1961.', NULL, NULL),
(1017, NULL, 'hint', '1961 Congo, 1965 Majlis Keselamatan, 1989 Namibia, 1990 Iran-Iraq, 1992 Somalia dan Bosnia, 2007 Lubnan.', 'Aku menyusun misi pasukan pengaman PBB. Congo pada 1961, ahli tidak tetap Majlis Keselamatan pada 1965, Namibia pada 1989, pemerhati di sempadan Iran-Iraq pada 1990, Somalia serta Bosnia dan Herzegovina pada 1992, dan Lubnan pada 2007.', 'Hebat! Kad misi pengaman tersusun dan Pemandu Pameran menampalnya di dinding.'),
(NULL, 'e10_n3_s2', 'hint', 'Tahun Majlis Keselamatan ialah 1965, 1989-1990, 1999-2000 dan 2015-2016.', NULL, NULL),
(1018, NULL, 'hint', 'Palestin-Israel, dadah di Vienna 1987, Tun Dr. Mahathir, UNESCO dan Majlis Keselamatan.', 'Aku memadankan sumbangan Malaysia dalam PBB. Konflik Palestin-Israel dengan penyelesaian yang adil dan berkekalan, Persidangan Dadah Vienna 1987 yang dipengerusikan Tun Dr. Mahathir, Pendidikan untuk Semua melalui UNESCO, dan keahlian tidak tetap Majlis Keselamatan pada 1965, 1989-1990, 1999-2000 dan 2015-2016.', 'Betul! Pelawat pameran membaca padanan itu dan mengangguk.'),
(NULL, 'e10_n3_s3', 'hint', 'Pinjaman Bank Pembangunan Islam ialah faedah OIC.', NULL, NULL),
(1019, NULL, 'hint', 'Mempertahankan kepentingan negara dan menyumbang pandangan dalam isu global.', 'Penyertaan dalam PBB membolehkan Malaysia memelihara dan mempertahankan kepentingan negara dalam keputusan PBB, menyumbang pendapat dalam pelbagai isu global dan meningkatkan komitmen menangani pelbagai isu.', 'Tepat! Kad faedah PBB itu dipilih dengan betul.'),
(NULL, 'e10_n3_s4', 'hint', 'Perhimpunan Agung PBB sesi ke-51 pada 1996 hingga 1997.', NULL, NULL),
(1020, NULL, 'hint', 'Razali Ismail 1989-1990 dan 1996-1997. Mazlan Othman angkasa lepas. Sijil dan pingat PBB.', 'Tan Sri Razali Ismail menjadi Pengerusi Majlis Keselamatan PBB pada 1989-1990 dan Pengerusi Perhimpunan Agung PBB sesi ke-51 pada 1996-1997. Datuk Dr. Mazlan Othman Pengarah Hal Ehwal Angkasa Lepas PBB, dan Pasukan Pengaman PBB diiktiraf dengan sijil dan pingat.', 'Betul! Pameran tokoh Malaysia di PBB kini lengkap.'),
(NULL, 'e10_n3_s5', 'hint', 'Taman Kinabalu dan Gunung Mulu diiktiraf pada tahun 2000.', NULL, NULL),
(1021, NULL, 'hint', 'Empat bukti. Gunung dalam kaca, gua batu kapur, peta bandar dan hologram tengah.', 'Aku mencari empat bukti warisan dunia. Taman Kinabalu di Sabah dan Taman Negara Gunung Mulu di Sarawak, warisan alam 2000, Melaka dan George Town warisan 2008, dan Warisan Arkeologi Lembah Lenggong 2012.', 'Cekap! Keempat-empat tapak warisan dunia dijumpai dalam ruang UNESCO.'),
(NULL, 'e10_n3_s6', 'hint', 'Hikayat Hang Tuah, Sulalatus Salatin dan Batu Bersurat Terengganu.', NULL, NULL),
(1022, NULL, 'hint', 'Alam semula jadi, kebudayaan, Memori Dunia dan Warisan Budaya Tidak Ketara.', 'Aku memadankan kategori UNESCO. Alam semula jadi ialah Gunung Mulu dan Taman Kinabalu, kebudayaan ialah Melaka, George Town dan Lembah Lenggong, Memori Dunia ialah Hikayat Hang Tuah, Sulalatus Salatin dan Batu Bersurat Terengganu, dan warisan tidak ketara ialah Makyung, Dondang Sayang, Silat dan Wangkang.', 'Tepat! Kategori UNESCO tersusun dengan contoh yang betul.'),
(NULL, 'e10_n3_s7', 'hint', 'Wangkang diiktiraf pada tahun 2020.', NULL, NULL),
(1023, NULL, 'hint', '2000, 2001, 2005, 2008, 2012, 2018, 2019 dan 2020.', 'Aku menyusun pengiktirafan UNESCO. Gunung Mulu dan Taman Kinabalu pada 2000, Hikayat Hang Tuah pada 2001, Makyung pada 2005, Melaka dan George Town pada 2008, Lembah Lenggong pada 2012, Dondang Sayang pada 2018, Silat pada 2019 dan Wangkang pada 2020.', 'Betul! Kad pengiktirafan tersusun dan Pemandu Pameran bertepuk tangan.'),
(NULL, 'e10_n3_s8', 'hint', 'Dasar Malaysia ialah berbaik-baik dengan semua negara.', NULL, NULL),
(1024, NULL, 'hint', 'Menjamin keselamatan dan kemakmuran rakyat serta negara.', 'Malaysia mengamalkan dasar berbaik-baik dengan semua negara dan bertanggungjawab memastikan kestabilan politik, kemajuan ekonomi dan keharmonian rakyat. Hubungan baik dengan negara luar menjamin keselamatan dan kemakmuran rakyat serta negara.', 'Tepat! Kad penutup pameran dipilih dengan betul.'),
(NULL, 'e10_n3_s9', 'hint', 'Tiga peringkat. Diri, masyarakat dan negara.', NULL, NULL),
(1025, NULL, 'hint', 'Diri memelihara hubungan baik dengan jiran. Masyarakat membentuk perpaduan. Negara dihormati dan disegani.', 'Aku belajar tiga peringkat hubungan baik. Diri memelihara hubungan baik dengan jiran supaya keharmonian terpupuk, masyarakat membentuk perpaduan yang mendatangkan faedah kepada semua, dan negara dihormati serta disegani melalui kesepakatan.', 'Tahniah! Pemandu Pameran menyerahkan lencana kenang-kenangan Pameran Malaysia dan Dunia kepadamu.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(221, 1001, NULL, 'Tugasku mewakili suara muda di sidang ASEAN. Jika fakta silap, wakil negara lain akan menyangka Malaysia tidak bersedia, {nama}.', 1),
(221, 1001, NULL, 'Aku belajar bahawa hubungan baik dengan negara jiran memelihara keharmonian dan menjadikan negara dihormati.', 2),
(221, 1001, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wakil muda yang menghadiri sidang ASEAN. Dengar hujah wakil lain dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(221, 1001, 'e10_n1_s1', 'Sidang serantau bermula sebentar lagi dan aku keliru dengan tiga singkatan ini. Tolong aku sebelum wakil lain tiba.', 1),
(231, 1001, 'e10_n1_s1', 'Aku Wakil Indonesia. SEAFET ditubuhkan pada tahun 1959 dan anggotanya Persekutuan Tanah Melayu, Thailand dan Filipina.', 2),
(231, 1001, 'e10_n1_s1', 'ASA pula ditubuhkan pada tahun 1961 dengan Persekutuan Tanah Melayu, Thailand dan Filipina juga. ASEAN lahir pada tahun 1967 dan pada awalnya dianggotai lima buah negara.', 3),
(NULL, 1001, 'e10_n1_s1', 'Aku akan padankan pertubuhan, tahun dan anggotanya.', 4),
(221, 1001, 'e10_n1_s1', 'Jangan salah kerana nota sidang akan tercemar. Mengapakah negara berjiran perlu bekerjasama?', 5),
(224, 1001, 'e10_n1_s2', 'Aku Pakar Ekonomi ASEAN. Keluarga ASEAN membesar sedikit demi sedikit, bukan sekali gus.', 1),
(224, 1001, 'e10_n1_s2', 'Pada tahun 1959 Malaysia menyertai SEAFET. Pada tahun 1961 Persekutuan Tanah Melayu menyertai ASA. Pada tahun 1967 ASEAN ditubuhkan dengan lima negara awal.', 2),
(231, 1001, 'e10_n1_s2', 'Brunei menyertai pada tahun 1984. Vietnam menyertai pada tahun 1995, dan Laos serta Myanmar menyertai serentak pada tahun 1997.', 3),
(231, 1001, 'e10_n1_s2', 'Kemboja menyertai pada tahun 1999, lalu genaplah sepuluh negara anggota.', 4),
(NULL, 1001, 'e10_n1_s2', 'Aku akan susun peristiwa itu mengikut tahun.', 5),
(221, 1001, 'e10_n1_s2', 'Susun betul-betul kerana nanti peta jadi salah. Mengapakah anggota ASEAN terus bertambah?', 6),
(221, 1001, 'e10_n1_s3', 'Bilik sidang ini penuh dengan petunjuk tentang ASEAN. Aku mahu empat daripadanya.', 1),
(231, 1001, 'e10_n1_s3', 'Bendera Malaysia di sana menunjukkan Malaysia tuan rumah Mesyuarat Menteri Luar ASEAN. Peta Asia Tenggara di dinding menunjukkan ASEAN dianggotai 10 negara Asia Tenggara.', 2),
(224, 1001, 'e10_n1_s3', 'Bendera Singapura menunjukkan Singapura salah satu negara awal ASEAN. Dokumen perjanjian di meja menyatakan matlamat keamanan dan kestabilan politik.', 3),
(NULL, 1001, 'e10_n1_s3', 'Bendera Malaysia, peta Asia Tenggara, bendera Singapura dan dokumen perjanjian. Aku akan cari keempat-empatnya.', 4),
(221, 1001, 'e10_n1_s3', 'Teliti supaya tiada yang terlepas. Jadi apakah yang dijamin oleh kerjasama serantau?', 5),
(231, 1001, 'e10_n1_s4', 'Kad latar belakang ASEAN ini terkoyak. Boleh kamu bacakan semula?', 1),
(224, 1001, 'e10_n1_s4', 'ASEAN ditubuhkan pada 8 Ogos 1967 dan kini dianggotai oleh 10 buah negara Asia Tenggara.', 2),
(224, 1001, 'e10_n1_s4', 'Ibu pejabat ASEAN terletak di Jakarta, Indonesia. Tarikh 31 Ogos 1957 ialah hari kemerdekaan Tanah Melayu, dan 16 September 1963 ialah hari Malaysia dibentuk.', 3),
(NULL, 1001, 'e10_n1_s4', 'Aku akan pilih kad yang betul. 8 Ogos 1967, 10 negara dan ibu pejabat di Jakarta.', 4),
(221, 1001, 'e10_n1_s4', 'Cepat kerana sidang bermula. Dan apakah peranan Malaysia semasa ASEAN ditubuhkan?', 5),
(224, 1001, 'e10_n1_s5', 'ASEAN ada empat matlamat dan aku selalu menyebutnya dalam ucapan. Bantu aku sebut semuanya.', 1),
(231, 1001, 'e10_n1_s5', 'Keamanan bermaksud menjamin keamanan dan kestabilan politik. Pertumbuhan bermaksud menggalakkan pertumbuhan ekonomi, kemajuan sosial dan pembangunan kebudayaan.', 2),
(231, 1001, 'e10_n1_s5', 'Kerjasama bermaksud menjalin kerjasama dalam bidang latihan dan penyelidikan. Kesejahteraan bermaksud meningkatkan taraf hidup penduduk.', 3),
(NULL, 1001, 'e10_n1_s5', 'Aku akan padankan empat matlamat itu dengan maksudnya.', 4),
(221, 1001, 'e10_n1_s5', 'Teliti supaya laporan tepat. Apakah faedah hubungan baik dengan jiran?', 5),
(221, 1001, 'e10_n1_s6', 'Lihat logo ASEAN di dinding ini. Setiap warna dan bentuk ada maknanya.', 1),
(231, 1001, 'e10_n1_s6', 'Warna biru melambangkan keamanan dan kestabilan. Warna merah melambangkan semangat dan dinamisme.', 2),
(231, 1001, 'e10_n1_s6', 'Warna kuning melambangkan kemakmuran dan warna putih melambangkan kesucian. Sepuluh tangkai padi melambangkan impian pengasasan ASEAN yang diikat persahabatan dan perpaduan, dan bulatan melambangkan kesatuan ASEAN.', 3),
(NULL, 1001, 'e10_n1_s6', 'Aku akan padankan warna dan bentuk dengan maknanya.', 4),
(221, 1001, 'e10_n1_s6', 'Teliti kerana ini maruah ASEAN. Apakah yang diingatkan oleh logo itu kepada kita?', 5),
(224, 1001, 'e10_n1_s7', 'Apa sahaja yang Malaysia dapat daripada ASEAN? Aku mahu kamu senaraikan faedahnya.', 1),
(231, 1001, 'e10_n1_s7', 'Dari segi keamanan dan kestabilan politik, Deklarasi Kuala Lumpur 1971 mengisytiharkan ZOPFAN. Dari segi pertumbuhan ekonomi, ada projek perindustrian baja urea di Bintulu, Sarawak.', 2),
(231, 1001, 'e10_n1_s7', 'Dari segi pertumbuhan sosial, Malaysia menjadi tuan rumah penganjuran Sukan SEA. Dari segi latihan dan penyelidikan, RECSAM dibina di Pulau Pinang.', 3),
(NULL, 1001, 'e10_n1_s7', 'Aku akan padankan faedah itu dengan buktinya.', 4),
(221, 1001, 'e10_n1_s7', 'Jangan lupa ZOPFAN kerana ia penting. Jadi dengan siapakah faedah ini dikongsi?', 5),
(224, 1001, 'e10_n1_s8', 'Dokumen ini menyenaraikan sumbangan Malaysia kepada ASEAN, tetapi senarainya bercampur dengan pertubuhan lain.', 1),
(231, 1001, 'e10_n1_s8', 'Malaysia menjadi tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN dan membantu menangani isu pencerobohan Vietnam terhadap Kemboja.', 2),
(231, 1001, 'e10_n1_s8', 'Malaysia juga membantu meredakan konflik politik di selatan Filipina, mengutarakan penubuhan ZOPFAN dan menyertai Pertubuhan Menteri-Menteri Pelajaran ASEAN atau SEAMEO.', 3),
(NULL, 1001, 'e10_n1_s8', 'Aku akan pilih sumbangan yang betul. Mengutarakan ZOPFAN dan membantu meredakan konflik di selatan Filipina.', 4),
(221, 1001, 'e10_n1_s8', 'Jangan campur dengan sumbangan PBB. Dan apakah perasaan negara anggota terhadap Malaysia?', 5),
(222, 1002, NULL, 'Tugasku menjaga keamanan dan mengenali setiap pertubuhan. Jika aku keliru, bantuan akan sampai ke tempat yang salah, {nama}.', 1),
(222, 1002, NULL, 'Aku belajar bahawa Malaysia menyumbang kepada keamanan dunia melalui rundingan perdamaian dan hubungan baik dengan negara luar.', 2),
(222, 1002, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga keamanan PBB dengan topi biru. Peka kepada setiap perubahan di sekeliling. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(222, 1002, 'e10_n2_s1', 'Aku Penjaga Keamanan PBB. Hari ini kita meronda dewan sidang ini untuk mencari empat petunjuk.', 1),
(225, 1002, 'e10_n2_s1', 'Dewan sidang ini menunjukkan keahlian PBB terbuka kepada semua negara. Bendera Malaysia menunjukkan Malaysia negara anggota PBB yang aktif menyumbang.', 2),
(225, 1002, 'e10_n2_s1', 'Peta dunia di skrin menunjukkan pasukan pengaman PBB termasuk Malaysia. Peta di skrin utama menunjukkan kawasan tugas pasukan pengaman PBB.', 3),
(NULL, 1002, 'e10_n2_s1', 'Dewan sidang, bendera Malaysia, peta dunia dan peta di skrin utama. Aku akan cari keempat-empatnya.', 4),
(222, 1002, 'e10_n2_s1', 'Teliti kerana ini dewan antarabangsa. Jadi apakah tugas pasukan pengaman itu?', 5),
(225, 1002, 'e10_n2_s2', 'Wakil baharu selalu keliru tentang PBB. Bacakan kad latar belakangnya.', 1),
(222, 1002, 'e10_n2_s2', 'PBB ditubuhkan pada 24 Oktober 1945 selepas Perang Dunia Kedua. Keahliannya terbuka kepada semua negara di seluruh dunia.', 2),
(222, 1002, 'e10_n2_s2', 'Ibu pejabat PBB terletak di New York, Amerika Syarikat. Bahasa rasminya ialah bahasa Arab, Mandarin, Inggeris, Perancis, Rusia dan Sepanyol, iaitu enam bahasa rasmi.', 3),
(NULL, 1002, 'e10_n2_s2', 'Aku akan pilih kad yang betul. 24 Oktober 1945, ibu pejabat di New York dan enam bahasa rasmi.', 4),
(225, 1002, 'e10_n2_s2', 'Tepat atau wakil baharu akan keliru. Dan apakah yang dijamin oleh PBB?', 5),
(226, 1002, 'e10_n2_s3', 'Aku Utusan Komanwel. Malaysia menyertai Komanwel pada tahun 1957, dan Komanwel dianggotai bekas tanah jajahan British.', 1),
(225, 1002, 'e10_n2_s3', 'Malaysia menyertai PBB pada tahun 1957 juga. Keahlian PBB terbuka kepada semua negara.', 2),
(228, 1002, 'e10_n2_s3', 'Aku Duta NAM. Malaysia menyertai Pergerakan Negara-negara Berkecuali sejak tahun 1970, dan NAM dianggotai 120 negara membangun dari Asia, Afrika dan Amerika Selatan.', 3),
(227, 1002, 'e10_n2_s3', 'OIC pula disertai Malaysia sejak penubuhannya pada 1969, dan awalnya dianggotai 57 negara.', 4),
(NULL, 1002, 'e10_n2_s3', 'Aku akan padankan pertubuhan antarabangsa itu dengan butirannya.', 5),
(226, 1002, 'e10_n2_s3', 'Teliti dan jangan campur. Apakah dasar yang diamalkan oleh Malaysia dengan semua pertubuhan ini?', 6),
(226, 1002, 'e10_n2_s4', 'Dokumen Komanwel ini luntur. Boleh bacakan semula?', 1),
(226, 1002, 'e10_n2_s4', 'Komanwel dibentuk pada 11 Disember 1931 dan dianggotai oleh 54 buah negara bekas tanah jajahan British kecuali Mozambique dan Republik Rwanda.', 2),
(226, 1002, 'e10_n2_s4', 'Ibu pejabat Sekretariat Komanwel terletak di London, England. Matlamatnya membina semangat setia kawan dan mewujudkan kerjasama dalam pendidikan, ekonomi, kesihatan serta belia dan sukan.', 3),
(NULL, 1002, 'e10_n2_s4', 'Aku akan pilih dokumen yang betul. Dibentuk 1931, 54 negara dan Sekretariat di London.', 4),
(226, 1002, 'e10_n2_s4', 'Jangan terburu-buru. Dan apakah yang dibina oleh Komanwel antara negara anggota?', 5),
(226, 1002, 'e10_n2_s5', 'Malaysia mendapat banyak faedah daripada Komanwel dalam empat bidang.', 1),
(226, 1002, 'e10_n2_s5', 'Dalam pendidikan, ada tawaran biasiswa Komanwel untuk melanjutkan pendidikan tinggi. Dalam perdagangan, barangan Malaysia mudah menembusi pasaran antarabangsa.', 2),
(226, 1002, 'e10_n2_s5', 'Dalam kesihatan, maklumat dan data dikongsi untuk menangani wabak seperti COVID-19. Dalam belia dan sukan, Sukan Komanwel dianjurkan di Malaysia pada tahun 1998.', 3),
(NULL, 1002, 'e10_n2_s5', 'Aku akan padankan bidang itu dengan faedahnya.', 4),
(226, 1002, 'e10_n2_s5', 'Bagus, padankan satu demi satu. Jadi apakah yang ditawarkan oleh Komanwel kepada banyak bidang?', 5),
(226, 1002, 'e10_n2_s6', 'Nota ini menyebut dua sumbangan besar Malaysia dalam Komanwel.', 1),
(226, 1002, 'e10_n2_s6', 'Malaysia mengecam dasar Aparteid di Afrika Selatan yang membezakan penduduk mengikut warna kulit dan membantu menamatkannya pada tahun 1993.', 2),
(226, 1002, 'e10_n2_s6', 'Malaysia juga menjadi tuan rumah Commonwealth Heads of Government Meeting atau CHOGM pada tahun 1989 dan mengisytiharkan Deklarasi Langkawi 1989 tentang pencemaran alam sekitar.', 3),
(NULL, 1002, 'e10_n2_s6', 'Aku akan pilih sumbangan yang betul. Menamatkan Aparteid pada 1993 dan Deklarasi Langkawi 1989.', 4),
(226, 1002, 'e10_n2_s6', 'Jangan campur dengan sumbangan organisasi lain. Dan apakah yang dikecam serta dipelihara oleh Malaysia?', 5),
(227, 1002, 'e10_n2_s7', 'Aku Wakil OIC. Kad latar belakang ini tertulis tentang pengasas kami.', 1),
(230, 1002, 'e10_n2_s7', 'Aku Tunku Abdul Rahman. OIC ditubuhkan pada 25 September 1969 dan aku dilantik sebagai Setiausaha Agung OIC yang pertama.', 2),
(227, 1002, 'e10_n2_s7', 'Pejabat OIC terletak di Jeddah, Arab Saudi dan OIC dianggotai 57 buah negara. Bahasa rasminya ialah bahasa Arab, Inggeris dan Perancis.', 3),
(NULL, 1002, 'e10_n2_s7', 'Aku akan pilih kad yang betul. Setiausaha Agung pertama, pejabat di Jeddah dan 57 negara.', 4),
(227, 1002, 'e10_n2_s7', 'Jangan salah kerana nanti Tunku tersinggung. Dan apakah yang dikukuhkan oleh OIC?', 5),
(229, 1002, 'e10_n2_s8', 'Aku Sukarelawan Kemanusiaan OIC. Bantu aku menyusun sumbangan Malaysia.', 1),
(227, 1002, 'e10_n2_s8', 'Malaysia membantu penubuhan Bank Pembangunan Islam pada tahun 1975. Malaysia menangani isu Bosnia dan Herzegovina pada tahun 1991.', 2),
(227, 1002, 'e10_n2_s8', 'Malaysia menubuhkan Universiti Islam Antarabangsa Malaysia atau UIAM pada tahun 1983. Malaysia menjadi tuan rumah Persidangan OIC pada tahun 1974 dan 2003.', 3),
(229, 1002, 'e10_n2_s8', 'Malaysia juga menyokong penuh perjuangan rakyat Palestin menentang kekejaman Israel.', 4),
(NULL, 1002, 'e10_n2_s8', 'Aku akan padankan sumbangan itu dengan butirannya.', 5),
(229, 1002, 'e10_n2_s8', 'Cepat kerana laporan tahunan sudah dekat. Jadi mengapa penglibatan Malaysia dalam OIC penting?', 6),
(223, 1003, NULL, 'Tugasku membimbing pelawat melalui pameran dengan fakta yang tepat. Jika aku silap, pelawat akan membawa pulang cerita yang salah, {nama}.', 1),
(223, 1003, NULL, 'Aku belajar bahawa pengiktirafan antarabangsa perlu dikekalkan dan hubungan baik menjadikan negara dihormati serta disegani.', 2),
(223, 1003, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemandu pameran UNESCO. Sambut pelawat dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(223, 1003, 'e10_n3_s1', 'Selamat datang ke Pameran Malaysia dan Dunia. Bilik ini menyimpan misi pasukan pengaman PBB, tetapi kad-kadnya bertaburan.', 1),
(222, 1003, 'e10_n3_s1', 'Aku Penjaga Keamanan PBB. Pada tahun 1961 Malaysia menghantar pasukan pengaman PBB ke Congo. Pada tahun 1965 Malaysia menjadi ahli tidak tetap Majlis Keselamatan PBB.', 2),
(222, 1003, 'e10_n3_s1', 'Pada tahun 1989 pasukan pengaman dihantar ke Namibia. Pada tahun 1990 pasukan pemerhati PBB dihantar ke sempadan Iran-Iraq.', 3),
(222, 1003, 'e10_n3_s1', 'Pada tahun 1992 pasukan pengaman dihantar ke Somalia dan Bosnia dan Herzegovina. Pada tahun 2007 pasukan pengaman Malaysia bertugas di Lubnan.', 4),
(NULL, 1003, 'e10_n3_s1', 'Aku akan susun misi itu mengikut tahun.', 5),
(223, 1003, 'e10_n3_s1', 'Betulkan urutannya kerana ini sejarah negara. Apakah yang dilakukan oleh pasukan pengaman itu untuk dunia dan Malaysia?', 6),
(225, 1003, 'e10_n3_s2', 'Aku Wakil PBB. Pandangan Malaysia sering didengar di dewan ini dan aku mahu kamu padankan sumbangannya.', 1),
(225, 1003, 'e10_n3_s2', 'Mengenai konflik Palestin-Israel, Malaysia mencari penyelesaian yang adil dan berkekalan. Mengenai penyalahgunaan dadah, ada Persidangan Antarabangsa Dadah di Vienna pada Jun 1987.', 2),
(225, 1003, 'e10_n3_s2', 'Presiden persidangan dadah 1987 ialah Tun Dr. Mahathir Mohamad, Perdana Menteri keempat. Dalam mutu pendidikan, Malaysia memperjuangkan prinsip Pendidikan untuk Semua melalui UNESCO.', 3),
(225, 1003, 'e10_n3_s2', 'Malaysia ahli tidak tetap Majlis Keselamatan PBB pada tahun 1965, 1989 hingga 1990, 1999 hingga 2000 dan 2015 hingga 2016.', 4),
(NULL, 1003, 'e10_n3_s2', 'Aku akan padankan isu, tokoh dan penggal itu.', 5),
(223, 1003, 'e10_n3_s2', 'Teliti kerana pelawat menunggu. Bagaimanakah pandangan Malaysia disuarakan di PBB?', 6),
(223, 1003, 'e10_n3_s3', 'Kad-kad ini bertanya apa faedah Malaysia menyertai PBB.', 1),
(225, 1003, 'e10_n3_s3', 'Penyertaan dalam PBB membolehkan Malaysia memelihara dan mempertahankan kepentingan negara dalam sebarang keputusan yang diambil oleh PBB.', 2),
(225, 1003, 'e10_n3_s3', 'Malaysia juga meneruskan peranan aktif dengan menyumbang pendapat dan pandangan dalam pelbagai isu global serta meningkatkan komitmen menangani pelbagai isu.', 3),
(NULL, 1003, 'e10_n3_s3', 'Aku akan pilih faedah yang betul. Mempertahankan kepentingan negara dan menyumbang pandangan dalam isu global.', 4),
(223, 1003, 'e10_n3_s3', 'Pilih dengan teliti. Jadi apakah yang diperoleh apabila kita aktif dalam PBB?', 5),
(225, 1003, 'e10_n3_s4', 'Tiga tokoh dan satu pasukan ini mengharumkan nama Malaysia di PBB.', 1),
(225, 1003, 'e10_n3_s4', 'Tan Sri Razali Ismail menjadi Pengerusi Majlis Keselamatan PBB pada tahun 1989 hingga 1990, dan Pengerusi Perhimpunan Agung PBB sesi ke-51 pada tahun 1996 hingga 1997.', 2),
(225, 1003, 'e10_n3_s4', 'Datuk Dr. Mazlan Othman menjadi Pengarah Hal Ehwal Angkasa Lepas PBB. Pasukan Pengaman PBB pula diiktiraf melalui sijil dan pingat perkhidmatan PBB.', 3),
(NULL, 1003, 'e10_n3_s4', 'Aku akan padankan tokoh dan pasukan itu dengan jawatan mereka.', 4),
(223, 1003, 'e10_n3_s4', 'Teliti kerana ini pengiktirafan antarabangsa. Mengapakah pengiktirafan itu perlu dikekalkan?', 5),
(223, 1003, 'e10_n3_s5', 'Ini ruang UNESCO. Dalam kaca-kaca ini ada empat tapak warisan dunia Malaysia. Cari semuanya.', 1),
(222, 1003, 'e10_n3_s5', 'Gunung dalam kaca ialah Taman Kinabalu di Sabah, warisan alam 2000. Gua batu kapur ialah Taman Negara Gunung Mulu di Sarawak, warisan 2000 juga.', 2),
(223, 1003, 'e10_n3_s5', 'Peta bandar dalam kaca ialah Melaka dan George Town, warisan 2008. Hologram di tengah ialah Warisan Arkeologi Lembah Lenggong, 2012.', 3),
(NULL, 1003, 'e10_n3_s5', 'Taman Kinabalu, Gunung Mulu, Melaka dan George Town serta Lembah Lenggong. Aku akan cari keempat-empatnya.', 4),
(223, 1003, 'e10_n3_s5', 'Teliti dan jangan terlepas. Jadi apa yang perlu kita lakukan terhadap warisan dunia itu?', 5),
(223, 1003, 'e10_n3_s6', 'UNESCO mengiktiraf warisan Malaysia dalam empat kategori. Boleh padankan?', 1),
(223, 1003, 'e10_n3_s6', 'Tapak Warisan Dunia Alam Semula Jadi ialah Taman Negara Gunung Mulu dan Taman Kinabalu. Tapak Warisan Dunia Kebudayaan ialah Melaka, George Town dan Lembah Lenggong.', 2),
(223, 1003, 'e10_n3_s6', 'Daftar Memori Dunia ialah Hikayat Hang Tuah, Sulalatus Salatin dan Batu Bersurat Terengganu. Daftar Warisan Budaya Tidak Ketara ialah Makyung, Dondang Sayang, Silat dan Wangkang.', 3),
(NULL, 1003, 'e10_n3_s6', 'Aku akan padankan kategori dengan contohnya.', 4),
(225, 1003, 'e10_n3_s6', 'Teliti kerana ini pengiktirafan PBB. Apakah yang ditunjukkan oleh pengiktirafan UNESCO itu?', 5),
(223, 1003, 'e10_n3_s7', 'Tarikh-tarikh pengiktirafan UNESCO ini bertaburan di lantai. Siapa boleh susun?', 1),
(223, 1003, 'e10_n3_s7', 'Pada tahun 2000 Taman Negara Gunung Mulu dan Taman Kinabalu diiktiraf. Pada tahun 2001 Hikayat Hang Tuah diiktiraf Daftar Memori Dunia.', 2),
(223, 1003, 'e10_n3_s7', 'Pada tahun 2005 Makyung diiktiraf. Pada tahun 2008 Melaka dan George Town diiktiraf, dan pada tahun 2012 Warisan Arkeologi Lembah Lenggong diiktiraf.', 3),
(223, 1003, 'e10_n3_s7', 'Pada tahun 2018 Dondang Sayang diiktiraf, pada tahun 2019 Silat diiktiraf dan pada tahun 2020 Wangkang diiktiraf.', 4),
(NULL, 1003, 'e10_n3_s7', 'Aku akan susun pengiktirafan itu mengikut tahun.', 5),
(225, 1003, 'e10_n3_s7', 'Teliti kerana ada banyak tahun. Dan apakah yang perlu kita usahakan terhadap pengiktirafan itu?', 6),
(225, 1003, 'e10_n3_s8', 'Kad penutup ini bertanya, mengapa hubungan baik dengan negara luar penting?', 1),
(223, 1003, 'e10_n3_s8', 'Malaysia mengamalkan dasar berbaik-baik dengan semua negara dan bertanggungjawab memastikan kestabilan politik, kemajuan ekonomi serta keharmonian rakyatnya.', 2),
(223, 1003, 'e10_n3_s8', 'Hubungan baik dengan negara luar penting bagi menjamin keselamatan dan kemakmuran rakyat serta negara.', 3),
(NULL, 1003, 'e10_n3_s8', 'Aku akan pilih jawapan yang betul. Menjamin keselamatan dan kemakmuran rakyat serta negara.', 4),
(225, 1003, 'e10_n3_s8', 'Fikir tentang keselamatan dan kemakmuran. Jadi bagaimanakah negara lain memandang negara yang berbaik-baik dengan semua?', 5),
(223, 1003, 'e10_n3_s9', 'Pameran ini hampir tamat. Satu soalan terakhir, apakah peranan diri, masyarakat dan negara?', 1),
(225, 1003, 'e10_n3_s9', 'Diri memelihara hubungan baik dengan jiran supaya keharmonian dapat dipupuk.', 2),
(225, 1003, 'e10_n3_s9', 'Masyarakat membentuk perpaduan dan hubungan baik mendatangkan faedah kepada semua. Negara pula menikmati kesepakatan yang menjadikan negara dihormati serta disegani.', 3),
(NULL, 1003, 'e10_n3_s9', 'Aku akan padankan diri, masyarakat dan negara dengan peranannya.', 4),
(223, 1003, 'e10_n3_s9', 'Jangan campur aduk. Apakah yang dipastikan oleh pandangan dan sumbangan Malaysia kepada dunia?', 5);
INSERT INTO QuestionBank (bankID, eraID) VALUES (10, 10)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(1001, 10, 'Malaysia menyertai SEAFET pada tahun...', '1961', '1959', '1967', '1984', 'B', 'Pertubuhan serantau pertama.', 'Malaysia menyertai SEAFET pada tahun 1959.'),
(1002, 10, 'Persekutuan Tanah Melayu menyertai ASA pada tahun...', '1961', '1959', '1967', '1957', 'A', 'Bersama Thailand dan Filipina.', 'Persekutuan Tanah Melayu menyertai ASA pada tahun 1961.'),
(1003, 10, 'ASEAN ditubuhkan pada...', '31 Ogos 1957', '16 September 1963', '24 Oktober 1945', '8 Ogos 1967', 'D', 'Lima negara awal.', 'ASEAN ditubuhkan pada 8 Ogos 1967.'),
(1004, 10, 'Lima negara awal ASEAN ialah Malaysia, Indonesia, Thailand, Filipina dan...', 'Brunei', 'Vietnam', 'Singapura', 'Kemboja', 'C', 'Brunei menyertai pada 1984.', 'Lima negara awal ASEAN termasuk Singapura.'),
(1005, 10, 'Brunei menyertai ASEAN pada tahun...', '1995', '1984', '1997', '1999', 'B', 'Anggota baharu pertama.', 'Brunei menyertai ASEAN pada tahun 1984.'),
(1006, 10, 'Ibu pejabat ASEAN terletak di...', 'Jakarta, Indonesia', 'Kuala Lumpur, Malaysia', 'Bangkok, Thailand', 'Manila, Filipina', 'A', 'Bukan di Malaysia.', 'Ibu pejabat ASEAN terletak di Jakarta.'),
(1007, 10, 'Berapakah negara anggota ASEAN kini?', '5', '7', '12', '10', 'D', 'Sepuluh tangkai padi pada logo.', 'ASEAN kini dianggotai 10 buah negara Asia Tenggara.'),
(1008, 10, 'Warna biru pada logo ASEAN melambangkan...', 'kemakmuran', 'kesucian', 'keamanan dan kestabilan', 'semangat dan dinamisme', 'C', 'Mengenai matlamat utama.', 'Warna biru melambangkan keamanan dan kestabilan.'),
(1009, 10, 'Deklarasi Kuala Lumpur 1971 mengisytiharkan ASEAN sebagai...', 'Kawasan Perdagangan Bebas', 'Kawasan Aman, Bebas dan Berkecuali (ZOPFAN)', 'Kawasan Larangan Terbang', 'Kawasan Ekonomi Khas', 'B', 'Mengelakkan campur tangan kuasa luar.', 'Deklarasi itu mengisytiharkan ASEAN sebagai ZOPFAN.'),
(1010, 10, 'Pembinaan Regional Centre for Education in Science and Mathematic (RECSAM) dibuat di...', 'Pulau Pinang', 'Bintulu', 'Langkawi', 'Kuching', 'A', 'Faedah latihan dan penyelidikan.', 'RECSAM dibina di Pulau Pinang.'),
(1011, 10, 'Komanwel dibentuk pada...', '24 Oktober 1945', '25 September 1969', '8 Ogos 1967', '11 Disember 1931', 'D', 'Bekas tanah jajahan British.', 'Komanwel dibentuk pada 11 Disember 1931.'),
(1012, 10, 'Ibu pejabat Sekretariat Komanwel terletak di...', 'New York', 'Jeddah', 'London, England', 'Jakarta', 'C', 'Dalam England.', 'Sekretariat Komanwel di London, England.'),
(1013, 10, 'Malaysia mengecam dasar Aparteid di...', 'Congo', 'Afrika Selatan', 'Namibia', 'Somalia', 'B', 'Membezakan penduduk mengikut warna kulit.', 'Malaysia mengecam dasar Aparteid di Afrika Selatan.'),
(1014, 10, 'Aparteid ditamatkan hasil desakan negara Komanwel pada tahun...', '1993', '1989', '1975', '2003', 'A', 'Malaysia membantu menamatkannya.', 'Aparteid ditamatkan pada tahun 1993.'),
(1015, 10, 'Malaysia menjadi tuan rumah CHOGM dan mengisytiharkan Deklarasi Langkawi pada tahun...', '1993', '1974', '2003', '1989', 'D', 'Berkaitan alam sekitar.', 'CHOGM dan Deklarasi Langkawi pada tahun 1989.'),
(1016, 10, 'Deklarasi Langkawi 1989 berkaitan dengan...', 'perdagangan bebas', 'kebebasan media', 'mengawal pencemaran alam sekitar', 'penghapusan Aparteid sahaja', 'C', 'Alam sekitar.', 'Deklarasi Langkawi berkaitan pengawalan pencemaran alam sekitar.'),
(1017, 10, 'OIC ditubuhkan pada...', '24 Oktober 1945', '25 September 1969', '11 Disember 1931', '8 Ogos 1967', 'B', 'Malaysia pengasasnya.', 'OIC ditubuhkan pada 25 September 1969.'),
(1018, 10, 'Setiausaha Agung OIC yang pertama ialah...', 'Tunku Abdul Rahman', 'Tun Abdul Razak', 'Tun Hussein Onn', 'Tun Dr. Mahathir', 'A', 'Perdana Menteri pertama Malaysia.', 'Tunku Abdul Rahman dilantik sebagai Setiausaha Agung OIC pertama.'),
(1019, 10, 'Pejabat OIC terletak di...', 'London', 'New York', 'Jakarta', 'Jeddah, Arab Saudi', 'D', 'Di Arab Saudi.', 'Pejabat OIC terletak di Jeddah, Arab Saudi.'),
(1020, 10, 'Awalnya OIC dianggotai oleh...', '10 buah negara', '54 buah negara', '57 buah negara', '120 buah negara', 'C', 'Matlamat memperkukuh perpaduan negara Islam.', 'OIC dianggotai oleh 57 buah negara.'),
(1021, 10, 'Bank Pembangunan Islam ditubuhkan dengan bantuan Malaysia pada tahun...', '1983', '1975', '1991', '2003', 'B', 'Sumbangan dalam OIC.', 'Malaysia membantu penubuhan Bank Pembangunan Islam pada 1975.'),
(1022, 10, 'Universiti Islam Antarabangsa Malaysia (UIAM) ditubuhkan pada tahun...', '1983', '1975', '1991', '1974', 'A', 'Sumbangan Malaysia dalam OIC.', 'UIAM ditubuhkan pada tahun 1983.'),
(1023, 10, 'Malaysia menjadi tuan rumah Persidangan OIC pada tahun...', '1969 dan 1975', '1983 dan 1991', '1989 dan 1993', '1974 dan 2003', 'D', 'Dua kali.', 'Malaysia menjadi tuan rumah persidangan OIC pada 1974 dan 2003.'),
(1024, 10, 'Pertubuhan Bangsa-Bangsa Bersatu (PBB) ditubuhkan pada...', '11 Disember 1931', '25 September 1969', '24 Oktober 1945', '8 Ogos 1967', 'C', 'Selepas Perang Dunia Kedua.', 'PBB ditubuhkan pada 24 Oktober 1945.'),
(1025, 10, 'Ibu pejabat PBB terletak di...', 'Geneva', 'New York, Amerika Syarikat', 'London', 'Jeddah', 'B', 'Di Amerika Syarikat.', 'Ibu pejabat PBB terletak di New York.'),
(1026, 10, 'PBB mempunyai berapa bahasa rasmi?', 'Enam', 'Tiga', 'Dua', 'Sepuluh', 'A', 'Arab, Mandarin, Inggeris, Perancis, Rusia, Sepanyol.', 'PBB mempunyai enam bahasa rasmi.'),
(1027, 10, 'Malaysia menyertai Komanwel dan PBB selepas mencapai kemerdekaan pada tahun...', '1963', '1967', '1970', '1957', 'D', 'Selepas 31 Ogos.', 'Malaysia menyertai Komanwel dan PBB selepas merdeka pada tahun 1957.'),
(1028, 10, 'Pergerakan Negara-negara Berkecuali (NAM) disertai Malaysia sejak tahun...', '1957', '1969', '1970', '1967', 'C', 'Anggotanya 120 negara membangun.', 'Malaysia menyertai NAM sejak tahun 1970.'),
(1029, 10, 'Pasukan pengaman PBB dari Malaysia pernah dihantar ke Congo pada tahun...', '1989', '1961', '1992', '2007', 'B', 'Misi pengaman pertama dalam senarai.', 'Pasukan pengaman Malaysia dihantar ke Congo pada tahun 1961.'),
(1030, 10, 'Malaysia menjadi ahli tidak tetap Majlis Keselamatan PBB pada tahun...', '1965, 1989-1990, 1999-2000 dan 2015-2016', '1957 sahaja', '1961 dan 1974', '2003 sahaja', 'A', 'Empat penggal.', 'Malaysia ahli tidak tetap Majlis Keselamatan pada empat penggal.'),
(1031, 10, 'Persidangan Antarabangsa Dadah di Vienna pada Jun 1987 dipengerusikan oleh...', 'Tunku Abdul Rahman', 'Tun Hussein Onn', 'Tun Abdullah', 'Tun Dr. Mahathir Mohamad', 'D', 'Perdana Menteri keempat.', 'Tun Dr. Mahathir diberi penghormatan sebagai Presiden persidangan itu.'),
(1032, 10, 'Prinsip ''Pendidikan untuk Semua'' diperjuangkan Malaysia melalui...', 'ASEAN', 'OIC', 'UNESCO', 'NAM', 'C', 'Agensi khas PBB.', 'Malaysia memperjuangkan prinsip itu melalui UNESCO.'),
(1033, 10, 'Siapakah Pengerusi Perhimpunan Agung PBB sesi ke-51 (1996-1997)?', 'Datuk Dr. Mazlan Othman', 'Tan Sri Razali Ismail', 'Tunku Abdul Rahman', 'Tun Dr. Mahathir', 'B', 'Juga Pengerusi Majlis Keselamatan 1989-1990.', 'Tan Sri Razali Ismail ialah Pengerusi Perhimpunan Agung PBB sesi ke-51.'),
(1034, 10, 'Datuk Dr. Mazlan Othman berkhidmat sebagai...', 'Pengarah Hal Ehwal Angkasa Lepas PBB', 'Setiausaha Agung OIC', 'Pengerusi Komanwel', 'Presiden ASEAN', 'A', 'Melaporkan aktiviti angkasa lepas.', 'Beliau Pengarah Hal Ehwal Angkasa Lepas PBB.'),
(1035, 10, 'Manakah Tapak Warisan Dunia kategori alam semula jadi (2000)?', 'Melaka dan George Town', 'Lembah Lenggong', 'Hikayat Hang Tuah', 'Taman Negara Gunung Mulu dan Taman Kinabalu', 'D', 'Sarawak dan Sabah.', 'Mulu dan Kinabalu diiktiraf pada tahun 2000.'),
(1036, 10, 'Melaka dan George Town diiktiraf Tapak Warisan Dunia pada tahun...', '2000', '2012', '2008', '2018', 'C', 'Bandar bersejarah Selat Melaka.', 'Melaka dan George Town diiktiraf pada tahun 2008.'),
(1037, 10, 'Manakah termasuk dalam Daftar Memori Dunia?', 'Makyung', 'Hikayat Hang Tuah', 'Silat', 'Wangkang', 'B', 'Manuskrip dan batu bersurat.', 'Hikayat Hang Tuah diiktiraf Daftar Memori Dunia pada 2001.'),
(1038, 10, 'Manakah termasuk dalam Daftar Warisan Budaya Tidak Ketara?', 'Makyung, Dondang Sayang, Silat dan Wangkang', 'Sulalatus Salatin dan Batu Bersurat Terengganu', 'Gunung Mulu dan Kinabalu', 'Lembah Lenggong sahaja', 'A', 'Seni persembahan dan tradisi.', 'Makyung, Dondang Sayang, Silat dan Wangkang ialah warisan budaya tidak ketara.'),
(1039, 10, 'Negara yang tidak mempunyai hubungan diplomatik dengan Malaysia ialah...', 'Thailand dan Filipina', 'Indonesia dan Singapura', 'Jepun dan Australia', 'Israel dan Korea Utara', 'D', 'Dasar Malaysia.', 'Malaysia tidak mengadakan hubungan diplomatik dengan Israel dan Korea Utara.'),
(1040, 10, 'Mengapakah hubungan baik dengan negara luar penting?', 'Menyebabkan negara dipinggirkan', 'Menjejaskan kestabilan politik', 'Menjamin keselamatan dan kemakmuran rakyat serta negara', 'Menghalang kemajuan ekonomi', 'C', 'Dasar berbaik-baik dengan semua negara.', 'Hubungan baik dengan negara luar menjamin keselamatan dan kemakmuran.'),
(1041, 10, 'Malaysia, Thailand dan Filipina menyertai SEAFET dan ASA sebelum ASEAN ditubuhkan. Apakah kesimpulan yang tepat?', 'ASEAN ditubuhkan tanpa sebarang kerjasama sebelumnya', 'Kerjasama serantau sudah bermula sebelum ASEAN dan diperluas melalui ASEAN', 'SEAFET dan ASA ialah pertubuhan dunia', 'Hanya Singapura terlibat sebelum 1967', 'B', 'Fikirkan urutan 1959, 1961 dan 1967.', 'SEAFET dan ASA ialah langkah awal kerjasama serantau yang kemudian diperluas dengan penubuhan ASEAN pada 1967.'),
(1042, 10, 'Projek baja urea di Bintulu dan pembinaan RECSAM di Pulau Pinang menunjukkan kerjasama ASEAN memberi faedah dalam bidang apa?', 'Pertumbuhan ekonomi serta latihan dan penyelidikan', 'Perang dan pertikaian sempadan', 'Penutupan perdagangan serantau', 'Pengurangan kerjasama pendidikan', 'A', 'Padankan projek dengan matlamat ASEAN.', 'Baja urea menyokong pertumbuhan ekonomi manakala RECSAM menyokong latihan dan penyelidikan.'),
(1043, 10, 'Sepuluh tangkai padi pada logo ASEAN diikat bersama. Apakah mesej yang paling sesuai untuk murid sekolah?', 'Setiap negara bekerja sendiri-sendiri', 'Padi hanya lambang pertanian', 'Ikatan itu lambang persaingan antara negara', 'Persahabatan dan perpaduan sepuluh negara menguatkan kesatuan serantau', 'D', 'Ingat makna ikatan dan bulatan.', 'Padi yang diikat melambangkan impian pengasasan ASEAN yang diikat persahabatan dan perpaduan, dan bulatan melambangkan kesatuan.'),
(1044, 10, 'Malaysia mengecam Aparteid dan mengisytiharkan Deklarasi Langkawi 1989. Apakah nilai yang dipaparkan oleh dua tindakan ini?', 'Kepentingan satu kaum sahaja', 'Sikap tidak peduli terhadap dunia', 'Keadilan sejagat dan tanggungjawab memelihara alam sekitar', 'Hanya mengutamakan perdagangan', 'C', 'Hubungkan Aparteid dengan warna kulit dan Langkawi dengan alam.', 'Mengecam Aparteid menunjukkan keadilan sejagat dan Deklarasi Langkawi menunjukkan tanggungjawab memelihara alam sekitar.'),
(1045, 10, 'Seorang murid ingin menjadi sukarelawan membantu mangsa konflik di luar negara. Pertubuhan manakah yang paling dekat dengan kerja Malaysia membantu isu Bosnia dan Herzegovina?', 'ASEAN', 'OIC', 'Komanwel', 'NAM', 'B', 'Ingat sumbangan Malaysia dalam OIC.', 'Malaysia membantu menangani isu Bosnia dan Herzegovina pada 1991 melalui OIC.'),
(1046, 10, 'Pasukan pengaman Malaysia bertugas di Congo, Namibia, Somalia dan Lubnan. Apakah kesan jangka panjang kepada imej negara?', 'Malaysia dihormati sebagai negara yang menyumbang kepada keamanan dunia', 'Malaysia dipinggirkan oleh dunia', 'Malaysia tidak lagi menjadi anggota PBB', 'Malaysia hanya mementingkan perdagangan', 'A', 'Fikirkan pengiktirafan sijil dan pingat PBB.', 'Misi pengaman menjadikan Malaysia dihormati dan mengharumkan nama negara.'),
(1047, 10, 'Hikayat Hang Tuah dan Silat sama-sama diiktiraf UNESCO tetapi dalam kategori berbeza. Pasangan manakah yang betul?', 'Kedua-duanya Tapak Warisan Dunia Alam Semula Jadi', 'Hikayat Hang Tuah warisan tidak ketara dan Silat memori dunia', 'Kedua-duanya Tapak Warisan Dunia Kebudayaan', 'Hikayat Hang Tuah dalam Daftar Memori Dunia dan Silat dalam Daftar Warisan Budaya Tidak Ketara', 'D', 'Satu ialah bahan bertulis, satu lagi seni dan amalan.', 'Hikayat Hang Tuah diiktiraf Daftar Memori Dunia pada 2001 manakala Silat diiktiraf Daftar Warisan Budaya Tidak Ketara pada 2019.'),
(1048, 10, 'Mengapakah Malaysia perlu berbaik-baik dengan semua negara walaupun pandangan politik berbeza?', 'Supaya hubungan dengan jiran terputus', 'Supaya perdagangan dihentikan', 'Supaya keselamatan, kestabilan politik dan kemakmuran rakyat terjamin', 'Supaya negara terasing daripada dunia', 'C', 'Ingat dasar berbaik-baik dengan semua negara.', 'Hubungan baik dengan negara luar menjamin keselamatan dan kemakmuran rakyat serta negara.'),
(1049, 10, 'Seorang murid berkawan dengan jiran yang berlainan kaum dan negara asal. Tindakannya sejajar dengan peranan yang mana?', 'Negara mengisytiharkan peperangan', 'Diri memelihara hubungan baik dengan jiran supaya keharmonian dipupuk', 'Masyarakat dipecahkan mengikut kaum', 'Dunia diasingkan daripada Malaysia', 'B', 'Ingat peranan diri, masyarakat dan negara.', 'Memelihara hubungan baik dengan jiran ialah peranan diri yang memupuk keharmonian, kemudian membentuk perpaduan masyarakat dan kesepakatan negara.');
